(function(A){Object.assign(A.D,{"G4869":{"l":"συναιχμάλωτος","o":3,"ar":"<f>*† <o>συν-αιχμάλωτος</o>، <g>-ου, ὁ </g></f> <s><b>رفيق في الأسر، شريك في السجن</b> (أصلاً عن أسير الحرب): <r v=\"Rom.16.7\"></r>، <r v=\"Col.4.10\"></r>، <r v=\"Phlm.1.23\"></r>.†</s>","en":"<f>*† <o>συν-αιχμάλωτος</o>, <g>-ου, ὁ </g></f> <s><b>a fellow prisoner</b> (prop., of a captive in war, v. Lft., <i>Col.</i>, 234): <r v=\"Rom.16.7\"></r>, <r v=\"Col.4.10\"></r>, <r v=\"Phlm.1.23\"></r>.†</s>"},"G4822":{"l":"συνβιβάζω","o":7,"ar":"<f><o>συν-βιβάζω</o></f> <s n=\"1.\"><b>يقرن</b> أو <b>يربط معًا، يوحِّد</b>: <r v=\"Eph.4.16\"></r>، <r v=\"Col.2.2\"></r>، <r v=\"Col.2.19\"></r>. </s> <s n=\"2.\"><b>يقارن، يتأمّل، يستنتج</b>: <r v=\"Acts.16.10\"></r>. </s> <s n=\"3.\"><b>يستدلّ، يُثبت، يبرهن</b>: <r v=\"Acts.9.22\"></r>. </s> <s n=\"4.\">كما في السبعينية (\"يونانية الترجمة\"، = <g>ἐμβιβάζω</g>، مجازيًا)، <b>يعلِّم، يُرشد</b>: <r v=\"1Cor.2.16\"></r>، <r v=\"Acts.19.33\"></r>، (قارن <r v=\"Col.2.2\"></r>).†</s>","en":"<f><o>συν-βιβάζω</o></f> <et> <e t=\"derivation\">(Rec. <g>συμ-</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Exod.4.12\"></r>, <r v=\"Exod.4.15\"></r>, <r v=\"Lev.10.11\"></r>, <r v=\"Judg.13.8\"></r>, <r v=\"Ps.32.8\"></r> (<h n=\"H3384\">ירה</h> hi.); <r v=\"Exod.18.16\"></r>, <r v=\"Deut.4.9\"></r>, <r v=\"Isa.40.13\"></r> (<h n=\"H3045\">ידע</h> hi.), <r v=\"Isa.40.14\"></r> (<h n=\"H995\">בּין</h> hi.), <r v=\"Dan.9.22\"></r> (<h n=\"H7919\">שׂכל</h> hi.) * ;] </e> </et> <s n=\"1.\"><b>to join</b> or <b>knit together, unite</b>: <r v=\"Eph.4.16\"></r>, <r v=\"Col.2.2\"></r> (but v. infr.), <r v=\"Col.2.19\"></r>. </s> <s n=\"2.\"><b>to compare, consider, conclude</b> (Plat.): <r v=\"Acts.16.10\"></r>. </s> <s n=\"3.\"><b>to deduce, prove, demonstrate</b> (Arist.): <r v=\"Acts.9.22\"></r>. </s> <s n=\"4.\">As in LXX (\"translation Greek,\" = <g>ἐμβιβάζω</g>, metaph.), <b>to teach, instruct</b>: <r v=\"1Cor.2.16\"></r>, <r v=\"Acts.19.33\"></r>, R, mg. (also in Vg., <r v=\"Col.2.2\"></r>, <l>instructi</l>, but v. supr.).†</s>"},"G4830":{"l":"συνμέτοχος","o":2,"ar":"<f>* <o>συν-μέτοχος</o>، <g>-ον</g>، </f> <s><b>مشارك مع</b>؛ بمعنى الاسم، <g>ὁ σ.</g>، <b>شريك</b>: مع المضاف إليه للشيء، <r v=\"Eph.3.6\"></r>؛ مع المضاف إليه للشخص، <r v=\"Eph.5.7\"></r>.†</s>","en":"<f>* <o>συν-μέτοχος</o> (Rec. <g>συμμ-</g>), <g>-ον</g>, </f> <s><b>partaking together with</b>; as subst., <g>ὁ σ.</g>, <b>a joint partaker</b> (c. dat. pers. et gen. rei, FlJ, <i>BJ</i>, i, 24, 6): c. gen. rei, <r v=\"Eph.3.6\"></r>; c. gen. pers., <r v=\"Eph.5.7\"></r> (Arist.).†</s>"},"G4886":{"l":"σύνδεσμος","o":4,"ar":"<f><o>σύν-δεσμος</o>، <g>-ου, ὁ</g></f> <s><b>ما يربط معًا، رباط</b>: عن أربطة الجسد، <r v=\"Col.2.19\"></r>. مجازيًا، <g>σ. ἀδικίας</g>، <r v=\"Acts.8.23\"></r>؛ <g>τ. τελειότητος</g>، <r v=\"Col.3.14\"></r>؛ <g>τ. εἰρήνης</g>، <r v=\"Eph.4.3\"></r>.†</s>","en":"<f><o>σύν-δεσμος</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>συνδέω</g></x>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H7195\">קשׁר</h>, <h n=\"H7001\">קטר</h>, etc. ;]</e> </et> <s><b>that which binds together, a bond</b>: of the ligaments of the body, <r v=\"Col.2.19\"></r>. Metaph., <g>σ. ἀδικίας</g>, <r v=\"Acts.8.23\"></r>; <g>τ. τελειότητος</g>, <r v=\"Col.3.14\"></r>; <g>τ. εἰρήνης</g>, <r v=\"Eph.4.3\"></r> (v. Lft., Col., ll. c.).†</s>"},"G4806":{"l":"συνζωοποιέω","o":2,"ar":"<f>*† <o>συν-ζωο-ποιέω</o>، <g>ῶ-</g>، </f> <s><b>يُحيي مع</b>؛ مجازيًا، عن الحياة الروحية: <g>τ. Χριστῷ</g>، <r v=\"Eph.2.5\"></r>؛ <g>σὺν τ. Χ.</g>، <r v=\"Col.2.13\"></r>.†</s>","en":"<f>*† <o>συν-ζωο-ποιέω</o> (Rec. <g>συζ-</g>), <g>ῶ-</g>, </f> <s><b>to make alive or quicken together with</b>; metaph., of the spiritual life: <g>τ. Χριστῷ</g>, <r v=\"Eph.2.5\"></r>; <g>σὺν τ. Χ.</g>, <r v=\"Col.2.13\"></r>.†</s>"},"G4862":{"l":"σύν","o":128,"ar":"<f><o>σύν</o> (الأتيكية القديمة <g>ξύν</g>)، </f> حرف جر مع القابل، <s>يعبِّر عن المرافقة والشركة والاشتمال. وقد أخذ يتراجع تدريجيًا أمام <g>μετά</g> مع المضاف إليه، ولذلك هو قليل نسبيًا في العهد الجديد، إذ هو نادر في متى<i>4</i>، ومرقس<i>6</i>، ويوحنا<i>3</i>، وفي غيرها (أمثلة <r v=\"Jas.1.11\"></r>، <r v=\"2Pet.1.18\"></r>) لا يرد إلا عند لوقا (الإنجيل وسفر الأعمال) وبولس. <b>مع، بصحبة</b>: عن المرافقة والمعاشرة، <r v=\"Luke.2.13\"></r>، <r v=\"John.21.3\"></r>، <r v=\"Acts.10.23\"></r>، وفي مواضع أخرى؛ <g>εἶναι σύν τινι</g>، <r v=\"Luke.7.12\"></r>، <r v=\"Acts.4.13\"></r>، <r v=\"Phil.1.23\"></r>، وفي مواضع أخرى؛ عن الانحياز (المناصرة)، <r v=\"Acts.4.13\"></r>؛ <g>οἱ σύν τινι (ὄντες)</g>، عن الأتباع أو الرفقاء أو الزملاء، <r v=\"Mark.2.26\"></r>، <r v=\"Luke.5.9\"></r>، <r v=\"Acts.5.17\"></r>، وفي مواضع أخرى؛ عن المعونة، <g>ἡ χάρις τ. θεοῦ σὺν ἐμοί</g>، <r v=\"1Cor.15.10\"></r>؛ عن شيئين أو أكثر معًا، بمعنى <g>καί</g> تقريبًا، <r v=\"Luke.23.11\"></r>، <r v=\"Acts.3.4\"></r> <r v=\"Acts.10.2\"></r> <r v=\"Acts.14.5\"></r> <r v=\"Acts.23.15\"></r>، <r v=\"Eph.3.18\"></r>؛ <g>σὺν Χριστῷ ζῆν</g>، <r v=\"2Cor.13.4\"></r>؛ <b>علاوة على</b>، <g>σὺν πᾶσι τούτοις</g>، <r v=\"Luke.24.21\"></r>. في التركيب: <b>مع</b> (<g>συνχαίρω</g>)، <b>معًا</b> (<g>συνωδίνω</g>)، <b>كليًّا (تمامًا)</b> (<g>συντελέω</g>).</s>","en":"<f><o>σύν</o> (old Att. <g>ξύν</g>), </f> prep. c. dat., <s>expressing association, fellowship and inclusion. It gradually gave way to <g>μετά</g>, c. gen. (cf. LS, s.v.; Bl., § 41, 3), and is therefore comparatively infrequent in NT, being rare in Mt<i>4</i>, Mk<i>6</i>, Jo<i>3</i>, and elsewhere (exx. <r v=\"Jas.1.11\"></r>, <r v=\"2Pet.1.18\"></r>) only in Lk (Gosp. and Ac) and Paul. <b>With, together with</b>: of companionship and association, <r v=\"Luke.2.13\"></r>, <r v=\"John.21.3\"></r>, <r v=\"Acts.10.23\"></r>, al.; <g>εἶναι σύν τινι</g>, <r v=\"Luke.7.12\"></r>, <r v=\"Acts.4.13\"></r>, <r v=\"Phil.1.23\"></r>, al.; of partisanship, <r v=\"Acts.4.13\"></r>; <g>οἱ σύν τινι (ὄντες)</g>, of attendants, companions or colleagues, <r v=\"Mark.2.26\"></r>, <r v=\"Luke.5.9\"></r>, <r v=\"Acts.5.17\"></r>, al.; of assistance, <g>ἡ χάρις τ. θεοῦ σὺν ἐμοί</g>, <r v=\"1Cor.15.10\"></r>; of two or more things together, almost = <g>καί</g>, <r v=\"Luke.23.11\"></r>, <r v=\"Acts.3.4\"></r> <r v=\"Acts.10.2\"></r> <r v=\"Acts.14.5\"></r> <r v=\"Acts.23.15\"></r>, <r v=\"Eph.3.18\"></r>; <g>σὺν Χριστῷ ζῆν</g>, <r v=\"2Cor.13.4\"></r>; <b>besides</b> (FlJ, LXX), <g>σὺν πᾶσι τούτοις</g>, <r v=\"Luke.24.21\"></r>. In composition: <b>with</b> (<g>συνχαίρω</g>), <b>together</b> (<g>συνωδίνω</g>), <b>altogether</b> (<g>συντελέω</g>).</s>"},"G4891":{"l":"συνεγείρω","o":3,"ar":"<f><o>συν-εγείρω </o></f> <s><b>يُقيم معًا</b>: مجازيًا، عن قيامة المسيحي السرّية مع المسيح، <r v=\"Eph.2.6\"></r>؛ المبني للمجهول، <r v=\"Col.2.12\"></r> <r v=\"Col.3.1\"></r>.†</s>","en":"<f><o>συν-εγείρω </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Exod.23.5\"></r> B2 (<h n=\"H5800\">עזב</h>), <r v=\"Isa.14.9\"></r> (<h n=\"H5782\">עוּר</h> pil.), <r v=\"4Macc.2.14\"></r> * ;]</e> </et> <s><b>to raise together</b>: metaph., of the Christian's mystical resur­rection with Christ, <r v=\"Eph.2.6\"></r>; pass., <r v=\"Col.2.12\"></r> <r v=\"Col.3.1\"></r>.†</s>"},"G4883":{"l":"συναρμολογέω","o":2,"ar":"<f>*† <o>συν-αρμολογέω</o>، <g>-ῶ</g></f> <s><b>يركِّب معًا</b> أو <b>يُحكِم الربط معًا (مركَّب معًا)</b>: عن أجزاء البناء، <r v=\"Eph.2.21\"></r>؛ عن أعضاء الجسد، <r v=\"Eph.4.16\"></r>.†</s>","en":"<f>*† <o>συν-αρμολογέω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἁρμός</g></x>, <x><g>λέγω</g></x>), = cl. <g>συναρμόζω</g>, </e> </et> <s><b>to fit</b> or <b>frame together</b>: of the parts of a building, <r v=\"Eph.2.21\"></r>; of the members of the body, <r v=\"Eph.4.16\"></r> (Eccl.).†</s>"},"G4847":{"l":"συνπολίτης","o":1,"ar":"<f>* <o>συν-πολίτης</o>، <g>-ου, ὁ</g> </f> <s><b>مواطن مع (رعية مع)</b>: الجمع، <g>σ. τ. ἁγίων</g>، عكس <g>ξένοι κ. πάροικοι</g>، <r v=\"Eph.2.19\"></r> .†</s>","en":"<f>* <o>συν-πολίτης</o> (Rec. <g>σνμπ-</g>), <g>-ου, ὁ</g> </f> <s><b>a fellow-citizen</b>: pl., <g>σ. τ. ἁγίων</g>, opp. to <g>ξένοι κ. πάροικοι</g>, <r v=\"Eph.2.19\"></r> (Eur.; <i>C.I.</i>, 6446; condemned by Atticists; v. Rutherford, <i>NPhr.</i>, 255 f.).†</s>"},"G4859":{"l":"σύμφωνος","o":1,"ar":"<f><o>σύμφωνος</o>، <g>-ον</g></f> <s><b>متوافق في الصوت</b>. مجازيًا، <b>متناغم، متفق</b>: <g>ἐκ συμφώνου</g>، <b>بالاتفاق، عن موافقة</b>، <r v=\"1Cor.7.5\"></r>.†</s>","en":"<f><o>σύμφωνος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <x><g>σύν</g></x>, <x><g>φωνή</g></x>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Eccl.7.14\"></r> (<h n=\"H5980\">לְעֻמַּת</h>), <r v=\"4Macc.7.7\"></r> <r v=\"4Macc.14.7\"></r> * ;]</e> </et> <s><b>agreeing in sound</b>. Metaph., <b>harmonious, agreeing</b>: <g>ἐκ συμφώνου</g> (for exx. from <g>π.</g>, v. Deiss., <i>BS</i>, 255), <b>by agreement</b>, <r v=\"1Cor.7.5\"></r>.†</s>"},"G4813":{"l":"συλάω","o":1,"ar":"<f>** <o>συλάω</o>، <g>-ῶ </g></f> <s>مع المنصوب للأشخاص، <b>يسلب، ينهب، يغنم</b>: <r v=\"2Cor.11.8\"></r>.†</s>","en":"<f>** <o>συλάω</o>, <g>-ῶ </g></f> <et> <e t=\"septuagint\">[in LXX: Ep. <r v=\"Jer.1.18\"></r> * ;] </e> </et> <s>c. acc. pers., <b>to strip, plunder, spoil</b>: <r v=\"2Cor.11.8\"></r>.†</s>"},"G4875":{"l":"συναναπαύομαι","o":1,"ar":"<f><o>συν-ανα-παύομαι </o></f> <s>مع القابل للشخص: <b>يضطجع ليستريح مع، ينام مع</b>. مجازيًا: <b>يستريح مع (ينتعش بالروح مع)</b>: <r v=\"Rom.15.32\"></r>.†</s>","en":"<f><o>συν-ανα-παύομαι </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Isa.11.6\"></r> (<h n=\"H7257\">רבץ</h>) * ;]</e> </et> <s>c. dat. pers., <b>to lie down to rest with, sleep with</b>. Metaph., <b>to be refreshed in spirit with</b>: <r v=\"Rom.15.32\"></r> (L, om.).†</s>"},"G4865":{"l":"συναγωνίζομαι","o":1,"ar":"<f>* <o>συν-αγωνίζομαι </o></f> <s><b>يجاهد مع، يعين</b> (أصلاً: عن المشاركة في مباراة): مع قابل الشخص والشيء، <r v=\"Rom.15.30\"></r>.†</s>","en":"<f>* <o>συν-αγωνίζομαι </o></f> <s><b>to strive together with, to help</b> (prop., of sharing in a contest): c. dat. pers. et rei, <r v=\"Rom.15.30\"></r>.†</s>"},"G4853":{"l":"συμφυλέτης","o":1,"ar":"<f>*† <o>συμ-φυλέτης</o>، <g>-ου, ὁ</g></f> <s><b>ابن العشيرة نفسها، ابن الوطن الواحد</b>: <r v=\"1Thess.2.14\"></r>. ولا ترد في موضع آخر.†</s>","en":"<f>*† <o>συμ-φυλέτης</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>σύν</g></x>, <x><g>φυλή</g></x>; cf. <g>σύμφυλος</g>, Aq.: <r v=\"Zech.13.7\"></r>; and v. Rutherford, <i>NPhr.</i>, 255 f.) </e> </et> <s><b>a fellow-tribesman, fellow-countryman</b>: <r v=\"1Thess.2.14\"></r> (v. M, <i>Th.</i>, in l., and Intr. liii). Not found elsewhere.†</s>"},"G4863":{"l":"συνάγω","o":59,"ar":"<f><o>συν-άγω </o></f> <s><b>جمع، ضمّ معًا</b>: عن الأشياء، <r v=\"John.6.12-John.6.13\"></r>؛ يليه <g>εἰς</g>، <r v=\"Matt.3.12\"></r>، وفي مواضع أخرى؛ <g>ἐκεῖ</g>، <r v=\"Luke.12.18\"></r>؛ <g>ποῦ</g>، <r v=\"Luke.12.17\"></r>؛ <g>συναγαγὼν πάντα</g> (أي <g>εἰς ἀργύριον</g>)، <b>باع كل شيء وحوّله إلى مال</b>: <r v=\"Luke.15.13\"></r>؛ عن الأشخاص، <r v=\"John.11.52\"></r>؛ خاصةً عن الاجتماعات، <r v=\"Matt.2.4\"></r>، <r v=\"John.11.47\"></r>، <r v=\"Acts.14.27\"></r>، وفي مواضع أخرى. المبني للمجهول: <b>اجتمع</b> أو <b>احتشد معًا</b>: <r v=\"Matt.22.41\"></r>، <r v=\"Mark.2.2\"></r>، <r v=\"Luke.22.66\"></r>، وفي مواضع أخرى؛ يليه <g>ἐπί</g> <r v=\"Mark.5.21\"></r>، <r v=\"Acts.4.27\"></r>؛ <g>πρός</g>، <r v=\"Matt.13.2\"></r>، <r v=\"Mark.4.1\"></r>، وفي مواضع أخرى؛ <g>εἰς</g>، <r v=\"Rev.19.17\"></r>؛ <g>ἐν</g>، <r v=\"Acts.11.26\"></r>؛ <g>μετά</g>، <r v=\"Matt.28.12\"></r>؛ <g>οὗ</g>، <r v=\"Matt.18.20\"></r>؛ <g>ὅπου</g>، <r v=\"Matt.26.57\"></r>؛ <g>ἐκεῖ</g>، <r v=\"John.18.2\"></r>، وفي مواضع أخرى. </s> <s>عند الكتّاب المتأخرين (قارن <r v=\"Deut.22.2\"></r>، وفي مواضع أخرى): <b>آوى، أضاف، استقبل ضيفًا</b>: <r v=\"Matt.25.35\"></r>، <r v=\"Matt.25.38\"></r>، <r v=\"Matt.25.43\"></r> (قارن <g>ἐπι-συνάγω</g>) </s>","en":"<f><o>συν-άγω </o></f> <et> <e t=\"septuagint\">[in LXX chiefly for<h n=\"H622\">אסף</h>, also for<h n=\"H6908\">קבץ</h>, etc. (cf. Kennedy, <i>Sources</i>, 128) ;] </e> </et> <s><b>to gather or bring together</b>: of things, <r v=\"John.6.12-John.6.13\"></r>; seq. <g>εἰς</g>, <r v=\"Matt.3.12\"></r>, al.; <g>ἐκεῖ</g>, <r v=\"Luke.12.18\"></r>; <g>ποῦ</g>, <r v=\"Luke.12.17\"></r>; <g>συναγαγὼν πάντα</g> (sc. <g>εἰς ἀργύριον</g>; v. Field, <i>Notes</i>, 68, MM, xxiv), <b>having sold off all</b>: <r v=\"Luke.15.13\"></r>; of persons, <r v=\"John.11.52\"></r>; esp. of assemblies, <r v=\"Matt.2.4\"></r>, <r v=\"John.11.47\"></r>, <r v=\"Acts.14.27\"></r>, al. Pass., <b>to be gathered</b> or <b>come together</b>: <r v=\"Matt.22.41\"></r>, <r v=\"Mark.2.2\"></r>, <r v=\"Luke.22.66\"></r>, al.; seq. <g>ἐπί</g> <r v=\"Mark.5.21\"></r>, <r v=\"Acts.4.27\"></r>; <g>πρός</g>, <r v=\"Matt.13.2\"></r>, <r v=\"Mark.4.1\"></r>, al.; <g>εἰς</g>, <r v=\"Rev.19.17\"></r>; <g>ἐν</g>, <r v=\"Acts.11.26\"></r>; <g>μετά</g>, <r v=\"Matt.28.12\"></r>; <g>οὗ</g>, <r v=\"Matt.18.20\"></r>; <g>ὅπου</g>, <r v=\"Matt.26.57\"></r>; <g>ἐκεῖ</g>, <r v=\"John.18.2\"></r>, al. </s> <s>In late writers (v. Kennedy, <i>Sources</i>, 128; cf. <r v=\"Deut.22.2\"></r>, al.), <b>to receive hospitably, entertain</b>: <r v=\"Matt.25.35\"></r>, <r v=\"Matt.25.38\"></r>, <r v=\"Matt.25.43\"></r> (cf. <g>ἐπι-συνάγω</g>) </s>"},"G4894":{"l":"συνεῖδον","o":2,"ar":"<f>** <o>συν-εῖδον </o> صيغة ماضٍ بسيط شاذة من <g>συνοράω</g> (انظر تحت مدخل <g>εἶδον</g>)، </f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>رأى معًا</b> أو <b>في الوقت نفسه</b>. </s> <s n=\"2.\"><b>أحاط بنظرة واحدة</b>، ومن ثم عن الإدراك العقلي: <b>أدرك، فهم، تبيّن</b>: <r v=\"Acts.12.12\"></r> <r v=\"Acts.14.6\"></r> (وعن الفعل القريب <g>σύνοιδα</g>، انظر تحت المدخل).†</s>","en":"<f>** <o>συν-εῖδον </o> irreg. aor. of <g>συνοράω</g> (v.s. <g>εἶδον</g>), </f> <et> <e t=\"septuagint\">[in LXX: <r v=\"1Macc.4.21\"></r><h>א</h>, <r v=\"2Macc.2.24\"></r> <r v=\"2Macc.4.4\"></r>, <r v=\"2Macc.4.41\"></r> R <r v=\"2Macc.5.17\"></r> <r v=\"2Macc.7.4\"></r>, <r v=\"2Macc.7.20\"></r> <r v=\"2Macc.8.8\"></r>, <r v=\"3Macc.2.8\"></r> A * ;] </e> </et> <s n=\"1.\"><b>to see together</b> or <b>at the same time</b> (Arist., Xen.). </s> <s n=\"2.\"><b>to see in one view</b>, hence, of mental vision, <b>to comprehend, understand</b> (LXX, Polyb., Plut., al.) : <r v=\"Acts.12.12\"></r> <r v=\"Acts.14.6\"></r> (on the related <g>σύνοιδα</g>, v. s.v.).†</s>"},"G4861":{"l":"σύνψυχος","o":1,"ar":"<f>*† <o>σύν-ψυχος</o>، <g>-ον</g> </f> <s><b>متّحد النفس، بنفس واحدة</b>: <r v=\"Phil.2.2\"></r>.†</s>","en":"<f>*† <o>σύν-ψυχος</o> (Rec. <g>συμ-</g>), <g>-ον</g> </f> <et> <e t=\"derivation\">(&lt; <x><g>ψυχή</g></x>), </e> </et> <s><b>of one mind</b>: <r v=\"Phil.2.2\"></r>.†</s>"},"G4893":{"l":"συνείδησις","o":30,"ar":"<f><o>συν-είδησις</o>، <g>-εως, ἡ</g></f> <s n=\"1.\"><b>وعي، إدراك</b>: مع المضاف إليه المفعول، <r v=\"Heb.10.2\"></r>، <r v=\"1Pet.2.19\"></r>. </s> <s n=\"2.\">بالمعنى الأخلاقي: التمييز الفطري، الوعي الذي يحكم على النفس، <b>الضمير</b>: <r v=\"Rom.2.15\"></r> <r v=\"Rom.9.1\"></r>، <r v=\"1Cor.10.29\"></r>، <r v=\"2Cor.1.12\"></r> <r v=\"2Cor.4.2\"></r> <r v=\"2Cor.5.11\"></r>، <r v=\"1Tim.4.2\"></r>، <r v=\"Heb.9.14\"></r>؛ <g>σ. ἀγαθή</g>، <r v=\"Acts.23.1\"></r>، <r v=\"1Tim.1.5\"></r>، <r v=\"1Tim.1.19\"></r>، <r v=\"1Pet.3.16\"></r>، <r v=\"1Pet.3.21\"></r>؛ <g>ἀσθενής</g>، <r v=\"1Cor.8.7\"></r>، <r v=\"1Cor.8.10\"></r>؛ <g>ἀσθενοῦσα</g>، <r v=\"1Cor.8.12\"></r>؛ <g>ἀπρόσκοπος</g>، <r v=\"Acts.24.16\"></r>؛ <g>καθαρά</g>، <r v=\"1Tim.3.9\"></r>، <r v=\"2Tim.1.3\"></r>؛ <g>καλή</g>، <r v=\"Heb.13.18\"></r>؛ <g>πονηρά</g>، <r v=\"Heb.10.22\"></r>؛ <g>ὁ νοῦς καὶ ἡ σ.</g>، <r v=\"Titus.1.15\"></r>؛ <g>διὰ τὴν σ.</g>، <r v=\"Rom.13.5\"></r>، <r v=\"1Cor.10.25\"></r>، <r v=\"1Cor.10.27-1Cor.10.28\"></r>؛ <g>κατὰ σ.</g>، <r v=\"Heb.9.9\"></r>؛ <g>ὑπὸ</g> (<g>τῆς</g>) <g>σ.</g>، <r v=\"John.8.9\"></r>، <r v=\"1Cor.10.29\"></r> (قارن <r v=\"Rom.2.15\"></r>).†</s>","en":"<f><o>συν-είδησις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>συνεῖδον</g></x>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Eccl.10.20\"></r> (<h n=\"H4093\">מַדָּע</h>), <r v=\"Wis.17.11\"></r>, <r v=\"Sir.42.18\"></r> <h>א</h> * ;] </e> </et> <s n=\"1.\"><b>consciousness</b>: c. gen. obj., <r v=\"Heb.10.2\"></r>, <r v=\"1Pet.2.19\"></r>. </s> <s n=\"2.\">In ethical sense, innate discernment, self-judging consciousness, <b>conscience</b> (Stoics and late writers): <r v=\"Rom.2.15\"></r> <r v=\"Rom.9.1\"></r>, <r v=\"1Cor.10.29\"></r>, <r v=\"2Cor.1.12\"></r> <r v=\"2Cor.4.2\"></r> <r v=\"2Cor.5.11\"></r>, <r v=\"1Tim.4.2\"></r>, <r v=\"Heb.9.14\"></r>; <g>σ. ἀγαθή</g>, <r v=\"Acts.23.1\"></r>, <r v=\"1Tim.1.5\"></r>, <r v=\"1Tim.1.19\"></r>, <r v=\"1Pet.3.16\"></r>, <r v=\"1Pet.3.21\"></r>; <g>ἀσθενής</g>, <r v=\"1Cor.8.7\"></r>, <r v=\"1Cor.8.10\"></r>; <g>ἀσθενοῦσα</g>, <r v=\"1Cor.8.12\"></r>; <g>ἀπρόσκοπος</g>, <r v=\"Acts.24.16\"></r>; <g>καθαρά</g>, <r v=\"1Tim.3.9\"></r>, <r v=\"2Tim.1.3\"></r>; <g>καλή</g>, <r v=\"Heb.13.18\"></r>; <g>πονηρά</g>, <r v=\"Heb.10.22\"></r>; <g>ὁ νοῦς καὶ ἡ σ.</g>, <r v=\"Titus.1.15\"></r>; <g>διὰ τὴν σ.</g>, <r v=\"Rom.13.5\"></r>, <r v=\"1Cor.10.25\"></r>, <r v=\"1Cor.10.27-1Cor.10.28\"></r>; <g>κατὰ σ.</g>, <r v=\"Heb.9.9\"></r>; <g>ὑπὸ</g> (<g>τῆς</g>) <g>σ.</g>, <r v=\"John.8.9\"></r> (Rec.), <r v=\"1Cor.10.29\"></r> (cf. Cremer, 233 ff.; <i>ICC</i> on <r v=\"Rom.2.15\"></r>; <i>DB</i>, i, 468 ff.).†</s>"},"G4851":{"l":"συμφέρω","o":15,"ar":"<f><o>συμ-φέρω </o></f> <s n=\"1.\">متعدٍّ: <b>جمع معًا</b>: مع المنصوب للشيء، <r v=\"Acts.19.19\"></r>. </s> <s n=\"2.\">لازم، وفي الغالب غير شخصي، <g>συμφέρει</g>، <b>يوافق، ينفع</b> أو <b>فيه فائدة</b>: <r v=\"1Cor.6.12\"></r> <r v=\"1Cor.10.23\"></r>، <r v=\"2Cor.8.10\"></r>؛ مع المصدر، <r v=\"Matt.19.10\"></r>، <r v=\"John.18.14\"></r>؛ مع القابل، يليه <g>ἵνα</g>، <r v=\"Matt.5.29-Matt.5.30\"></r> <r v=\"Matt.18.6\"></r>، <r v=\"John.11.50\"></r> <r v=\"John.16.7\"></r>. اسم الفاعل، <g>ςυμφέρων</g>، <b>نافع</b>: <r v=\"1Cor.12.7\"></r>؛ جمع، <r v=\"Acts.20.20\"></r>؛ (<g>οὐ σ.</g> أي <g>ἐστιν</g>؛ = <g>οὐ συμφέρει</g>)، <r v=\"2Cor.12.1\"></r>؛ اسمًا، <g>τὸ σ.</g>، <b>المنفعة</b>، <r v=\"Heb.12.10\"></r>.†</s>","en":"<f><o>συμ-φέρω </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Jer.26.14\"></r> (<h n=\"H2896\">טוֹב</h>), <r v=\"Prov.19.10\"></r> (<h n=\"H5000\">נָאוֶה</h>), <r v=\"Sir.30.19\"></r>, al. ;]</e> </et> <s n=\"1.\">trans. <b>to bring together</b>: c. acc. rei, <r v=\"Acts.19.19\"></r>. </s> <s n=\"2.\">Intrans., and mostly impers., <g>συμφέρει</g>, <b>it is expedient, profitable</b> or <b>an advantage</b>: <r v=\"1Cor.6.12\"></r> <r v=\"1Cor.10.23\"></r>, <r v=\"2Cor.8.10\"></r>; c. inf. (M, <i>Pr.</i>, 210), <r v=\"Matt.19.10\"></r>, <r v=\"John.18.14\"></r>; c. dat., seq. <g>ἵνα</g> (Bl., § 69, 5), <r v=\"Matt.5.29-Matt.5.30\"></r> <r v=\"Matt.18.6\"></r>, <r v=\"John.11.50\"></r> <r v=\"John.16.7\"></r>. Ptcp., <g>ςυμφέρων</g>, <b>profitable</b>: <r v=\"1Cor.12.7\"></r>; pl., <r v=\"Acts.20.20\"></r>; (<g>οὐ σ.</g> sc. <g>ἐστιν</g>; = <g>οὐ συμφέρει</g>; cf. Thuc., iii, 44, 2), <r v=\"2Cor.12.1\"></r>; as subst., <g>τὸ σ.</g>, <b>profit</b>, <r v=\"Heb.12.10\"></r>.†</s>"},"G4832":{"l":"σύμμορφος","o":2,"ar":"<f>*† <o>σύμ-μορφος</o>، <g>-ον</g></f> <s n=\"1.\">عند الكتّاب المتأخرين: مطلقًا، <b>مشابه</b>. </s> <s n=\"2.\"><b>مشابه لـ، على صورة</b>: مع القابل، <r v=\"Phil.3.21\"></r>؛ مع المضاف إليه، <r v=\"Rom.8.29\"></r>.†</s>","en":"<f>*† <o>σύμ-μορφος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <x><g>σύν</g></x>, <x><g>μορφή</g></x>), </e> </et> <s n=\"1.\">absol., <b>similar</b> (Luc.). </s> <s n=\"2.\"><b>con­formed to</b>: c. dat., <r v=\"Phil.3.21\"></r>; c. gen., <r v=\"Rom.8.29\"></r> (v. B1., § 36, 11; 37, 6).†</s>"},"G4828":{"l":"συνμαρτυρέω","o":3,"ar":"<f>* <o>συν-μαρτυρέω</o>، <g>-ῶ</g>، </f> <s><b>يشهد مع</b>: <r v=\"Rom.2.15\"></r>؛ مع القابل، <r v=\"Rom.8.16\"></r>؛ يليه <g>ὅτι</g>، <r v=\"Rom.9.1\"></r>.†</s>","en":"<f>* <o>συν-μαρτυρέω</o> (Rec. <g>συμμ-</g>), <g>-ῶ</g>, </f> <s><b>to bear witness with</b>: <r v=\"Rom.2.15\"></r>; c. dat., <r v=\"Rom.8.16\"></r>; seq. <g>ὅτι</g>, <r v=\"Rom.9.1\"></r>.†</s>"},"G4825":{"l":"σύμβουλος","o":1,"ar":"<f><o>σύμβουλος</o>، <g>-ου, ὁ</g></f> <s><b>مُشير، ناصح</b>: <r v=\"Rom.11.34\"></r> <i>(السبعينية)</i>.†</s>","en":"<f><o>σύμβουλος</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>σύν</g></x>, <x><g>βουλή</g></x>), </e> <e t=\"septuagint\">[in LXX for<h n=\"H3289\">יוֺעֵץ</h>and cogn. forms ;]</e> </et> <s><b>a counsellor, adviser</b>: <r v=\"Rom.11.34\"></r> <i>(LXX)</i>.†</s>"},"G4878":{"l":"συναντιλαμβάνομαι","o":2,"ar":"<f>† <o>συν-αντι-λαμβάνομαι </o></f> <s><b>يمسك مع آخر من جانبه لمساعدته</b>؛ ومن ثمّ: <b>يشارك في، يعين على الحمل</b>، وعمومًا: <b>يعين</b> (بتراكيب مختلفة، انظر السبعينية في المواضع المذكورة): مع القابل، <r v=\"Luke.10.40\"></r>، <r v=\"Rom.8.26\"></r>.†</s>","en":"<f>† <o>συν-αντι-λαμβάνομαι </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Gen.30.8\"></r> R (†), <r v=\"Exod.18.22\"></r>, <r v=\"Num.11.17\"></r> (<h n=\"H5375\">נשׂא</h>), <r v=\"Ps.89.21\"></r> (<h n=\"H3559\">כּוּן</h> ni.) * ;] </e> </et> <s><b>to take hold with at the side for assistance</b>; hence, <b>to take a share in, help in bearing</b>, and generally, <b>help</b> (with various constructions, v. LXX, ll. c., Deiss., <i>LAE</i>, 83 f.): c. dat., <r v=\"Luke.10.40\"></r>, <r v=\"Rom.8.26\"></r>.†</s>"},"G4800":{"l":"συνζάω","o":3,"ar":"<f>* <o>συν-ζάω</o>، </f> <s><b>يعيش مع</b>: عكس <g>συναποθανεῖν</g>، <r v=\"2Cor.7.3\"></r>؛ عن الحياة في الاتحاد بالمسيح، هنا وفيما بعد، <r v=\"Rom.6.8\"></r>، <r v=\"2Tim.2.11\"></r>.†</s>","en":"<f>* <o>συν-ζάω</o> (Rec. <g>συζ-</g>), </f> <s><b>to live with</b>: opp. to <g>συναποθανεῖν</g>, <r v=\"2Cor.7.3\"></r>; of life in union with Christ, here and hereafter, <r v=\"Rom.6.8\"></r>, <r v=\"2Tim.2.11\"></r>.†</s>"},"G4898":{"l":"συνέκδημος","o":2,"ar":"<f>*† <o>συν-έκδημος</o>، <g>-ου, ὁ</g></f> <s><b>رفيق سفر</b>: <r v=\"Acts.19.29\"></r>، <r v=\"2Cor.8.19\"></r>.†</s>","en":"<f>*† <o>συν-έκδημος</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>ἔκδημος</g>, <i>abroad</i>), </e> </et> <s><b>a fellow-traveller</b>: <r v=\"Acts.19.29\"></r>, <r v=\"2Cor.8.19\"></r>.†</s>"},"G4815":{"l":"συλλαμβάνω","o":16,"ar":"<f><o>συλ-λαμβάνω </o></f> <s n=\"1.\">مع المنصوب: <b>يجمع، يضمّ معًا</b>. </s> <s n=\"2.\"><b>يقبض على، يأخذ</b>: مع المنصوب للشخص، أسيرًا، <r v=\"Matt.26.55\"></r>، <r v=\"Mark.14.48\"></r>، <r v=\"Luke.22.54\"></r>، <r v=\"John.18.12\"></r>، <r v=\"Acts.1.16\"></r> <r v=\"Acts.12.3\"></r>؛ المبني للمجهول، <r v=\"Acts.23.27\"></r>؛ الصيغة الوسطى بمعنى المبني للمعلوم، <r v=\"Acts.26.21\"></r>؛ <g>σ. ἄγραν ἰχθύων</g>، <r v=\"Luke.5.9\"></r>. </s> <s n=\"3.\">مع القابل للشخص: <b>يشترك مع، يساعد، يُعين</b>؛ والصيغة الوسطى بالمعنى نفسه: <r v=\"Luke.5.7\"></r>، <r v=\"Phil.4.3\"></r>. </s> <s n=\"4.\">عن المرأة: <b>تحبل</b>: مطلقًا، <r v=\"Luke.1.24\"></r>؛ يليه <g>ἐν γαστρί</g>، <r v=\"Luke.1.31\"></r>؛ مع المنصوب، <r v=\"Luke.1.36\"></r>؛ وفي الموضع نفسه يليه <g>ἐν τ. κοιλίᾳ</g>، <r v=\"Luke.2.21\"></r>؛ مجازيًا، عن الشهوة التي تلد الخطية، <r v=\"Jas.1.15\"></r>.†</s>","en":"<f><o>συλ-λαμβάνω </o></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H8610\">תּפשׂ</h>, <h n=\"H2029\">הרה</h>, etc. ;]</e> </et> <s n=\"1.\">c. acc., <b>to bring together, collect</b>. </s> <s n=\"2.\"><b>to seize, take</b>: c. acc. pers., as a prisoner, <r v=\"Matt.26.55\"></r>, <r v=\"Mark.14.48\"></r>, <r v=\"Luke.22.54\"></r>, <r v=\"John.18.12\"></r>, <r v=\"Acts.1.16\"></r> <r v=\"Acts.12.3\"></r>; pass., <r v=\"Acts.23.27\"></r>; mid., in sense of act., <r v=\"Acts.26.21\"></r>; <g>σ. ἄγραν ἰχθύων</g>, <r v=\"Luke.5.9\"></r>. </s> <s n=\"3.\">C. dat. pers., <b>to take part with, assist, succour</b>; mid., in same sense: <r v=\"Luke.5.7\"></r>, <r v=\"Phil.4.3\"></r>. </s> <s n=\"4.\">Of a woman, <b>to conceive</b>: absol., <r v=\"Luke.1.24\"></r>; seq. <g>ἐν γαστρί</g>, <r v=\"Luke.1.31\"></r>; c. acc., <r v=\"Luke.1.36\"></r>; ib. seq. <g>ἐν τ. κοιλίᾳ</g>, <r v=\"Luke.2.21\"></r>; metaph., of lust producing sin, <r v=\"Jas.1.15\"></r>.†</s>"},"G4837":{"l":"συνπαρακαλέω","o":1,"ar":"<f>* <o>συν-παρα-καλέω</o>، <g>-ῶ</g>، </f> <s>في اليونانية الكلاسيكية: <b>يدعو أو يحثّ معًا</b>. المبني للمجهول: <b>يتشدّد أو يتعزّى مع الآخرين وبينهم</b>: <r v=\"Rom.1.12\"></r>.†</s>","en":"<f>* <o>συν-παρα-καλέω</o> (Rec. <g>συμπ-</g>), <g>-ῶ</g>, </f> <s><b>to call upon or exhort together</b> (Plat.). Pass., <b>to be strengthened or comforted with and among</b>: <r v=\"Rom.1.12\"></r>.†</s>"},"G4888":{"l":"συνδοξάζω","o":1,"ar":"<f>* <o>συν-δοξάζω </o></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>يشترك في الاستحسان</b>. </s> <s n=\"2.\">في العهد الجديد فقط: <b>يتمجّد مع</b>: المبني للمجهول، <r v=\"Rom.8.17\"></r>.†</s>","en":"<f>* <o>συν-δοξάζω </o></f> <s n=\"1.\"><b>to join in approving</b> (Arist.). </s> <s n=\"2.\">In NT only, <b>to glorify together</b>: pass., <r v=\"Rom.8.17\"></r>.†</s>"},"G4829":{"l":"συνμερίζω","o":1,"ar":"<f>† <o>συν-μερίζω</o></f> <s><b>يوزّع حصصًا</b>. الصيغة الوسطى: <b>يشارك في، يكون له نصيب في</b>: <r v=\"1Cor.9.13\"></r>.†</s>","en":"<f>† <o>συν-μερίζω</o></f> <et> <e t=\"derivation\">(Rec. <g>συμμ-</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Prov.29.24\"></r> <h>א</h><i>2</i> (<h n=\"H2505\">חלק</h>) * ;] </e> </et> <s><b>to distri­bute in shares</b>. Mid., <b>to have a share in</b>: <r v=\"1Cor.9.13\"></r> (Diod., al.).†</s>"},"G4879":{"l":"συναπάγω","o":3,"ar":"<f><o>συν-απ-άγω </o></f> <s><b>اقتاد مع</b> أو <b>معًا</b> (<r v=\"Exod.14.6\"></r>). المبني للمجهول، مجازيًا (مثل <g>συμπεριφέρομαι</g>): <b>انقاد مع</b>، <b>انجرف مع</b>: مع القابل: <r v=\"Gal.2.13\"></r>، <r v=\"2Pet.3.17\"></r>؛ عن مسايرة الأمور أو الأشخاص (<b>انقاد إلى، تنازل إلى</b>): <r v=\"Rom.12.16\"></r>.†</s>","en":"<f><o>συν-απ-άγω </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Exod.14.6\"></r> (<h n=\"H3947\">לקח</h>) * ;] </e> </et> <s><b>to lead away with</b> or <b>together</b> (<r v=\"Exod.14.6\"></r>). Pass., metaph. (as <g>συμπεριφέρομαι</g>, v. LS, s.v.), <b>to be carried away with</b>: c. dat., <r v=\"Gal.2.13\"></r>, <r v=\"2Pet.3.17\"></r>; of accommodating one­self to (EV, <b>condescend to</b>) things or persons (on the meaning, v. <i>ICC</i>, in l.; Field, <i>Notes</i>, 163), <r v=\"Rom.12.16\"></r>.†</s>"},"G4852":{"l":"σύνφημι","o":1,"ar":"<f>* <o>σύν-φημι</o>، </f> <s><b>يوافق، يُقرّ</b>: مع القابل، يليه <g>ὅτι</g>، <r v=\"Rom.7.16\"></r>.†</s>","en":"<f>* <o>σύν-φημι</o> (Rec. <g>συμ-</g>), </f> <s><b>to consent, confess</b>: c. dat., seq. <g>ὅτι</g>, <r v=\"Rom.7.16\"></r>.†</s>"},"G4889":{"l":"σύνδουλος","o":10,"ar":"<f><o>σύν-δουλος</o>، <g>-ου, ὁ </g> </f> <s><b>عبد رفيق</b>، <b>رفيق في الخدمة</b>: <r v=\"Matt.18.28-Matt.18.33\"></r> <r v=\"Matt.24.49\"></r>؛ عن خدام السيد الإلهي الواحد، <r v=\"Col.1.7\"></r> <r v=\"Col.4.7\"></r>، <r v=\"Rev.6.11\"></r>؛ وكذلك عن الملائكة، <r v=\"Rev.19.10\"></r> <r v=\"Rev.22.9\"></r>.†</s>","en":"<f><o>σύν-δουλος</o>, <g>-ου, ὁ </g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Ezra.4.7\"></r>, <r v=\"Ezra.4.9\"></r>, <r v=\"Ezra.4.17\"></r>, <r v=\"Ezra.4.23\"></r> <r v=\"Ezra.5.3\"></r>, <r v=\"Ezra.5.6\"></r> <r v=\"Ezra.6.6\"></r>, <r v=\"Ezra.6.13\"></r> (<h n=\"H3674\">כְּנָת</h>) * ;] </e> </et> <s><b>a fellow-servant</b>: <r v=\"Matt.18.28-Matt.18.33\"></r> <r v=\"Matt.24.49\"></r>; of servants of the same divine Lord, <r v=\"Col.1.7\"></r> <r v=\"Col.4.7\"></r>, <r v=\"Rev.6.11\"></r>; so of angels, <r v=\"Rev.19.10\"></r> <r v=\"Rev.22.9\"></r>.†</s>"},"G4882":{"l":"συναποστέλλω","o":1,"ar":"<f><o>συν-απο-στέλλω </o></f> <s><b>أرسل مع</b>: مع المنصوب، <r v=\"2Cor.12.18\"></r>.†</s>","en":"<f><o>συν-απο-στέλλω </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Exod.33.2\"></r>, <r v=\"Exod.33.12\"></r> (<h n=\"H7971\">שׁלח</h>), <r v=\"1Esd.5.2\"></r> * ;] </e> </et> <s><b>to send along with</b>: c. acc., <r v=\"2Cor.12.18\"></r> (cf. MM, xxiv).†</s>"},"G4842":{"l":"συνπέμπω","o":2,"ar":"<f>* <o>συν-πέμπω</o> </f> <s><b>أرسل مع</b>: مع المنصوب والقابل، <r v=\"2Cor.8.22\"></r>؛ ونفسه يليه <g>μετά</g> مع المضاف إليه، <r v=\"2Cor.8.18\"></r>.†</s>","en":"<f>* <o>συν-πέμπω</o> (Rec. <g>συμπ-</g>) </f> <s><b>to send together with</b>: c. acc. et dat., <r v=\"2Cor.8.22\"></r>; id. seq. <g>μετά</g>, c. gen., <r v=\"2Cor.8.18\"></r>.†</s>"},"G4819":{"l":"συμβαίνω","o":8,"ar":"<f><o>συμ-βαίνω </o></f> <s n=\"1.\"><b>وقف وقدماه متلاصقتان</b>. </s> <s n=\"2.\"><b>اجتمع، اتّفق</b>. </s> <s n=\"3.\">عن الأحداث: <b>حدث، جرى</b>: مع القابل للشخص، <r v=\"Mark.10.32\"></r>، <r v=\"Acts.3.10\"></r> <r v=\"Acts.20.19\"></r>، <r v=\"1Cor.10.11\"></r>، <r v=\"1Pet.4.12\"></r>، <r v=\"2Pet.2.22\"></r>؛ مطلقًا، <g>τὰ συμβεβηκότα</g>، <r v=\"Luke.24.14\"></r> (قارن <r v=\"1Macc.4.26\"></r>)؛ مع المنصوب والمصدر، <r v=\"Acts.21.35\"></r>.†</s>","en":"<f><o>συμ-βαίνω </o></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H6213\">עשׂה</h>, <h n=\"H7121\">קרא</h>, <h n=\"H7136\">קרה</h>, etc. ;] </e> </et> <s n=\"1.\"><b>to stand with the feet together</b>. </s> <s n=\"2.\"><b>to come together, come to terms</b>. </s> <s n=\"3.\">Of events, <b>to come to pass, happen</b>: c. dat. pers., <r v=\"Mark.10.32\"></r>, <r v=\"Acts.3.10\"></r> <r v=\"Acts.20.19\"></r>, <r v=\"1Cor.10.11\"></r>, <r v=\"1Pet.4.12\"></r>, <r v=\"2Pet.2.22\"></r>; absol., <g>τὰ συμβεβηκότα</g>, <r v=\"Luke.24.14\"></r> (cf. <r v=\"1Macc.4.26\"></r>); c. acc. et inf., <r v=\"Acts.21.35\"></r>.†</s>"},"G4841":{"l":"συνπάσχω","o":2,"ar":"<f>** <o>συν-πάσχω</o></f> <s n=\"1.\"><b>تألّم معًا أو مع</b>: <r v=\"Rom.8.17\"></r>، <r v=\"1Cor.12.26\"></r>. </s> <s n=\"2.\">في اليونانية الكلاسيكية: <b>تعاطف مع</b>.†</s>","en":"<f>** <o>συν-πάσχω</o></f> <et> <e t=\"derivation\">(Rec. <g>συμπ-</g>), </e> <e t=\"septuagint\">[in Al.: <r v=\"1Sam.22.8\"></r> * ;]</e> </et> <s n=\"1.\"><b>to suffer together or with</b>: <r v=\"Rom.8.17\"></r>, <r v=\"1Cor.12.26\"></r>. </s> <s n=\"2.\"><b>to sympathize with</b> (Plat., Arist.).†</s>"},"G4831":{"l":"συνμιμητής","o":1,"ar":"<f>*† <o>συν-μιμητής</o>، -οῦ, ὁ </f> <s><b>متمثّل مع آخرين، شريك في الاقتداء</b>: مع المضاف إليه للمفعول، <r v=\"Phil.3.17\"></r>. ولا ترد في موضع آخر.†</s>","en":"<f>*† <o>συν-μιμητής</o> (Rec. <g>συμμ-</g>), -οῦ, ὁ </f> <s><b>a fellow-imitator</b>: c. gen. obj., <r v=\"Phil.3.17\"></r> (v. <i>ICC</i>, in l.). Not elsewhere.†</s>"},"G4857":{"l":"συμφώνησις","o":1,"ar":"<f>*† <o>συμ-φώνησις</o>، <g>-εως, ἡ</g></f> <s><b>اتّفاق، وفاق</b>: يليه <g>πρός</g> مع المنصوب للشخص، <r v=\"2Cor.6.15\"></r>.†</s>","en":"<f>*† <o>συμ-φώνησις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>συμφωνέω</g></x>), </e> </et> <s><b>concord, agreement</b>: seq. <g>πρός</g>, c. acc. pers., <r v=\"2Cor.6.15\"></r>.†</s>"},"G4833":{"l":"συμμορφόω","o":null,"ar":"<f><o>συμ-μορφόω</o>، <g>-ῶ </g></f> <s>في النص المستلَم بدلاً من <g>-ίζω</g> (انظره)، <r v=\"Phil.3.10\"></r>.†</s>","en":"<f><o>συμ-μορφόω</o>, <g>-ῶ </g></f> <s>Rec. for <g>-ίζω</g> (q.v.), <r v=\"Phil.3.10\"></r>.†</s>"},"G4854":{"l":"σύμφυτος","o":1,"ar":"<f><o>σύμ-φυτος</o>، <g>-ον</g></f> <s n=\"1.\"><b>فطري، غريزي</b> (<r v=\"3Macc.3.22\"></r>). </s> <s n=\"2.\"><b>نامٍ معًا مع، متّحد مع</b>: <g>τ. ὁμοιώματι τ. θανάτου αὐτσῦ</g>، <r v=\"Rom.6.5\"></r>.†</s>","en":"<f><o>σύμ-φυτος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <g>συμφύω</g>, <b>to make to grow together</b>) </e> <e t=\"septuagint\">[in LXX: <r v=\"Zech.11.2\"></r> (<h n=\"H1219\">בּצר</h>), <r v=\"Ezra.7.7\"></r>, <r v=\"Ezra.7.8\"></r><h>א</h><i>2</i>, <r v=\"Amos.9.13\"></r>, <r v=\"3Macc.3.22\"></r> * ;]</e> </et> <s n=\"1.\"><b>congenital, innate</b> (Plat., al.; <r v=\"3Macc.3.22\"></r>). </s> <s n=\"2.\"><b>grown along with, united with</b>: <g>τ. ὁμοιώματι τ. θανάτου αὐτσῦ</g> (v. Field, <i>Notes</i>, 155 f.), <r v=\"Rom.6.5\"></r>.†</s>"},"G4812":{"l":"συλαγωγέω","o":1,"ar":"<f>*† <o>συλαγωγέω</o>، <g>-ῶ</g></f> <s><b>يسلب غنيمةً، يسبي</b>: مجازيًا، <r v=\"Col.2.8\"></r>.†</s>","en":"<f>*† <o>συλαγωγέω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>σύλη</g>, booty + <x><g>ἄγω</g></x>), </e> </et> <s><b>to carry off as spoil, lead captive</b> (<g>θυγατέρα</g>, Heliod., <i>Aeth.</i>, 10, 35): metaph., <r v=\"Col.2.8\"></r>.†</s>"},"G4880":{"l":"συναποθνήσκω","o":3,"ar":"<f>** <o>συν-απο-θνήσκω </o></f> <s><b>يموت مع</b> أو <b>معًا</b>: <r v=\"Mark.14.31\"></r>، <r v=\"2Cor.7.3\"></r>، <r v=\"2Tim.2.11\"></r>.†</s>","en":"<f>** <o>συν-απο-θνήσκω </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Sir.19.10\"></r> * ;] </e> </et> <s><b>to die with</b> or <b>together</b>: <r v=\"Mark.14.31\"></r>, <r v=\"2Cor.7.3\"></r> (v. Meyer, in l.), <r v=\"2Tim.2.11\"></r>.†</s>"},"G4866":{"l":"συναθλέω","o":2,"ar":"<f>* <o>συν-αθλέω</o>، <g>-ῶ </g></f> <s>= <g>συναγωνίζομαι</g> (يجاهد مع): مع القابل للمنفعة، <r v=\"Phil.1.27\"></r>؛ مع القابل للشخص، يليه <g>ἐν</g>، <r v=\"Phil.4.3\"></r>.†</s>","en":"<f>* <o>συν-αθλέω</o>, <g>-ῶ </g></f> <s>= <g>συναγωνίζομαι</g>: c. dat. commod., <r v=\"Phil.1.27\"></r>; c. dat. pers., seq. <g>ἐν</g>, <r v=\"Phil.4.3\"></r>.†</s>"},"G4821":{"l":"συμβουλεύω","o":2,"ar":"<f><o>συμ-βουλεύω </o></f> <s n=\"1.\"><b>ينصح، يشير على</b>: مع القابل للشخص، <r v=\"John.18.14\"></r>؛ ونفسه يليه المصدر، <r v=\"Rev.3.18\"></r>. </s> <s n=\"2.\">الصيغة الوسطى: <b>يتشاور، يأتمر</b>: يليه <g>ἵνα</g>، <r v=\"Matt.26.4\"></r> («صيغة وسطى تبادلية»)؛ مع المصدر، <r v=\"Acts.9.23\"></r>.†</s>","en":"<f><o>συμ-βουλεύω </o></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3289\">יעץ</h> ;] </e> </et> <s n=\"1.\"><b>to advise, counsel</b>: c. dat. pers., <r v=\"John.18.14\"></r>; id. seq. inf., <r v=\"Rev.3.18\"></r>. </s> <s n=\"2.\">Mid., <b>to take counsel, consult</b>: seq. <g>ἵνα</g>, <r v=\"Matt.26.4\"></r> (\"reciprocal middle,\" v. M, <i>Pr.</i>, 157); c. inf., <r v=\"Acts.9.23\"></r>.†</s>"},"G4874":{"l":"συναναμίγνυμι","o":3,"ar":"<f>* <o>συν-ανα-μίγνυμι</o></f> <s><b>يخلط معًا</b>؛ المبني للمجهول، بمعنى انعكاسي ومجازي: <b>يخالط، يعاشر</b>: <r v=\"1Cor.5.9\"></r>، <r v=\"1Cor.5.11\"></r>، <r v=\"2Thess.3.14\"></r>.†</s>","en":"<f>* <o>συν-ανα-μίγνυμι</o></f> <et> <e t=\"derivation\">(acc to Bl., 8, <g>-μείγνυμι</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Hos.7.8\"></r> A (<h n=\"H1101\">בּלל</h> hithpo.), <r v=\"Ezek.20.18\"></r> A * ;] </e> </et> <s><b>to mix up together</b>; pass., reflex, and metaph., <b>to associate with</b> (Plut., Ath., al.): <r v=\"1Cor.5.9\"></r>, <r v=\"1Cor.5.11\"></r>, <r v=\"2Thess.3.14\"></r> (v. M, <i>Th.</i>, 117).†</s>"},"G4804":{"l":"συνζητητής","o":1,"ar":"<f>*† <o>συν-ζητητής</o> (وفي بعض النصوص <g>συζ-</g>)، <g>-οῦ, ἁ</g> </f> <s><b>مُباحث، مجادل</b>: <r v=\"1Cor.1.20\"></r>.†</s>","en":"<f>*† <o>συν-ζητητής</o> (Rec. <g>συζ-</g>), <g>-οῦ, ἁ</g> </f> <et> <e t=\"derivation\">(&lt; <x><g>συνζητέω</g></x>), </e> </et> <s><b>a disputer, disputant</b>: <r v=\"1Cor.1.20\"></r>.†</s>"},"G4805":{"l":"σύνζυγος","o":1,"ar":"<f>** <o>σύν-ζυγος</o>، أو <g>Σύνζυγος, -ον</g> (اسم علم) </f> <s><b>شريك في النير، رفيق</b>. والأرجح أنه اسم علم، <g>Σ. γνήσιε</g>: <b>يا سوزيغس الصادق</b>، أي <b>من يصدق عليه اسمه</b>، <r v=\"Phil.4.3\"></r>.†</s>","en":"<f>** <o>σύν-ζυγος</o> (Rec. <g>ουζ-</g>), or as WH, mg., <g>Σύνζυγος, -ον</g> </f> <et> <e t=\"derivation\">(&lt; <x><g>συνζεύγνυμι</g></x>), </e> <e t=\"septuagint\">[in Aq., <r v=\"Ezek.23.21\"></r> * ;]</e> </et> <s><b>a yoke fellow</b>. Prob., as proper name, <g>Σ. γνήσιε</g>, <b>genuinely Synzygus, S. properly so-called</b>, <r v=\"Phil.4.3\"></r> (v. <i>ICC</i>, Lft., in l.; MM, xxiii).†</s>"},"G4838":{"l":"συνπαραλαμβάνω","o":4,"ar":"<f><o>συν-παρα-λαμβάνω</o></f> <s><b>أخذ معه</b>: رفيقًا، مع المنصوب، <r v=\"Acts.12.25\"></r> <r v=\"Acts.15.37-Acts.15.38\"></r>، <r v=\"Gal.2.1\"></r>.†</s>","en":"<f><o>συν-παρα-λαμβάνω</o></f> <et> <e t=\"derivation\">(Rec. <g>συμπ-</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Gen.19.17\"></r> (<h n=\"H5595\">ספה</h> ni.), <r v=\"Job.1.4\"></r> (<h n=\"H7971\">שׁלח</h>), <r v=\"3Macc.1.1\"></r> * ;]</e> </et> <s><b>to take along with</b>: as a companion, c. acc., <r v=\"Acts.12.25\"></r> <r v=\"Acts.15.37-Acts.15.38\"></r> (on the tenses, v. M, <i>Pr.</i>, 130), <r v=\"Gal.2.1\"></r>.†</s>"},"G4850":{"l":"συνπρεσβύτερος","o":1,"ar":"<f>*† <o>συν-πρεσβύτερος</o>، -ου, ὁ </f> <s><b>شيخ رفيق، زميل في المشيخة</b>: <r v=\"1Pet.5.1\"></r>.†</s>","en":"<f>*† <o>συν-πρεσβύτερος</o> (Rec. <g>συμπ-</g>), -ου, ὁ </f> <s><b>a fellow-elder</b>: <r v=\"1Pet.5.1\"></r> (Eccl.).†</s>"},"G4826":{"l":"Συμεών","o":7,"ar":"<f><o>Συμεών</o>، <g>ὁ </g> لا يُصرَّف، (بالعبرية <h n=\"H8095\">שִׁמְעוֹן</h>)، </f> <s><b>سمعان</b>، <b>شمعون</b> (قارن <r v=\"Luke.2.25\"></r>، <r v=\"Luke.2.34\"></r>)، اسم عبري كان يُستعمل بدله أيضًا الاسم اليوناني <g>Σίμων</g>، انظره؛ </s> <s n=\"1.\">ابن يعقوب (<r v=\"Gen.29.33\"></r>): <r v=\"Rev.7.7\"></r>. </s> <s n=\"2.\">أحد أسلاف ربنا: <r v=\"Luke.3.30\"></r> </s> <s n=\"3.\">شيخ متعبّد في الهيكل: <r v=\"Luke.2.25\"></r>، <r v=\"Luke.2.34\"></r>. </s> <s n=\"4.\">رجل يُلقَّب <b>نيجر</b>: <r v=\"Acts.13.1\"></r>. </s> <s n=\"5.\">الرسول <b>بطرس</b>: <r v=\"Acts.15.14\"></r>، <r v=\"2Pet.1.1\"></r>.†</s>","en":"<f><o>Συμεών</o>, <g>ὁ </g> indecl., (Heb. <h n=\"H8095\">שִׁמְעוֹן</h>), </f> <s><b>Simeon</b> (so always AV; RV in <r v=\"Luke.2.25\"></r>, <r v=\"Luke.2.34\"></r> only), <b>Symeon</b>, a Heb. name for which the Gk. <g>Σίμων</g>, q.v., was also used; </s> <s n=\"1.\">the son of Jacob (<r v=\"Gen.29.33\"></r>): <r v=\"Rev.7.7\"></r>. </s> <s n=\"2.\">An ancestor of our Lord: <r v=\"Luke.3.30\"></r> </s> <s n=\"3.\">An aged worshipper in the Temple: <r v=\"Luke.2.25\"></r>, <r v=\"Luke.2.34\"></r>. </s> <s n=\"4.\">One surnamed <b>Niger</b>: <r v=\"Acts.13.1\"></r>. </s> <s n=\"5.\">The apostle <b>Peter</b>: <r v=\"Acts.15.14\"></r>, <r v=\"2Pet.1.1\"></r> (R, txt., WH, txt., <g>Σίμων</g>).†</s>"},"G4876":{"l":"συναντάω","o":6,"ar":"<f><o>συν-αντάω</o>، <g>-ῶ </g></f> <s><b>لاقى</b>: مع القابل للشخص، <r v=\"Luke.9.18\"></r>، <r v=\"Luke.9.37\"></r> <r v=\"Luke.22.10\"></r>، <r v=\"Acts.10.25\"></r>، <r v=\"Heb.7.1\"></r>، <r v=\"Heb.7.10\"></r>. مجازيًا، عن الأحداث: <b>حدث، أصاب</b>: <r v=\"Acts.20.22\"></r>.†</s>","en":"<f><o>συν-αντάω</o>, <g>-ῶ </g></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H6293\">פּגע</h>,<h n=\"H6298\">פּגשׁ</h>,<h n=\"H7121\">קרא</h>,<h n=\"H7136\">קרה</h>, etc. ;]</e> </et> <s><b>to meet with</b>: c. dat. pers., <r v=\"Luke.9.18\"></r>, <r v=\"Luke.9.37\"></r> <r v=\"Luke.22.10\"></r>, <r v=\"Acts.10.25\"></r>, <r v=\"Heb.7.1\"></r>, <r v=\"Heb.7.10\"></r>. Metaph., of events, <b>to happen, befall </b>(Diog. L., Plut., al.): <r v=\"Acts.20.22\"></r>.†</s>"},"G4835":{"l":"συμπαθής","o":1,"ar":"<f><o>συμπαθής</o>، <g>-ές</g></f> <s n=\"1.\"><b>متأثر بالمشاعر نفسها، مشفق متعاطف</b>: <r v=\"1Pet.3.8\"></r>. </s> <s n=\"2.\"><b>مثير للشفقة</b> (<r v=\"Job.29.25\"></r>).†</s>","en":"<f><o>συμπαθής</o>, <g>-ές</g></f> <et> <e t=\"derivation\">(&lt; <x><g>σύν</g></x>, <x><g>πάσχω</g></x>) </e> <e t=\"septuagint\">[in LXX: <r v=\"Job.29.25\"></r> A (<h n=\"H57\">אֹבֵל</h>), <r v=\"4Macc.5.25\"></r><h>א</h>, <r v=\"4Macc.13.23\"></r> <r v=\"4Macc.15.4\"></r> * ;] </e> </et> <s n=\"1.\"><b>affected by like feelings, sympathetic</b>: <r v=\"1Pet.3.8\"></r>. </s> <s n=\"2.\"><b>exciting sympathy</b> (<r v=\"Job.29.25\"></r>; Dion. H.).†</s>"},"G4881":{"l":"συναπόλλυμι","o":1,"ar":"<f><o>συν-απ-όλλυμι </o></f> <s><b>أهلك مع</b> أو <b>معًا</b>. المبني للمجهول: <b>هلك معًا</b> (<b>مع</b>): مع قابل الشخص، <r v=\"Heb.11.31\"></r>.†</s>","en":"<f><o>συν-απ-όλλυμι </o></f> <et> <e t=\"septuagint\">[in LXX chiefly for<h n=\"H5595\">ספה</h>;] </e> </et> <s><b>to destroy with</b> or <b>together</b>. Pass., <b>to perish together</b> (<b>with</b>): c. dat. pers., <r v=\"Heb.11.31\"></r>.†</s>"},"G4864":{"l":"συναγωγή","o":56,"ar":"<f><o>συν-αγωγή</o>، <g>-ῆς, ἡ </g></f> <s>أصلاً، <b>جمع، ضمّ</b>؛ </s> <s n=\"1.\">عن الأشياء، </s> <s n=\"(a)\"><b>جمع</b> المحصول؛ </s> <s n=\"(b)\"><b>جمع</b> المال. </s> <s n=\"2.\">عن الأشخاص، </s> <s n=\"(a)\">عند الكتّاب المتأخرين: <b>جمع، حشد</b>؛ </s> <s n=\"(b)\"><b>اجتماع، مجمع</b>: <r v=\"Rev.2.9\"></r>، <r v=\"Rev.3.9\"></r>؛ خاصةً عن الاجتماع الديني اليهودي، <b>مجمع</b>: <r v=\"Luke.12.11\"></r>، <r v=\"Acts.9.2\"></r>، وفي مواضع أخرى؛ عن اجتماع مسيحي، <r v=\"Jas.2.2\"></r>. وكنايةً عن المبنى الذي يُعقد فيه الاجتماع، <b>مجمع</b>: <r v=\"Matt.10.17\"></r>، <r v=\"Mark.1.21\"></r>، وفي مواضع أخرى. </s>","en":"<f><o>συν-αγωγή</o>, <g>-ῆς, ἡ </g></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5712\">עֵדָה</h>, also for <h n=\"H6951\">קהל</h>, etc. ;] </e> </et> <s>prop., <b>a bringing together</b>; </s> <s n=\"1.\">of things, </s> <s n=\"(a)\"><b>a gathering in</b> of harvest; </s> <s n=\"(b)\"><b>a collection</b> of money. </s> <s n=\"2.\">Of persons, </s> <s n=\"(a)\"><b>a collecting, assembling</b> (Polyb.); </s> <s n=\"(b)\"><b>an assembly</b> (MM, xxiv; Deiss., <i>LAE</i>, 101 ff.): <r v=\"Rev.2.9\"></r> <r v=\"Rev.3.9\"></r>; esp. of a Jewish religious assembly, <b>a synagogue</b>: <r v=\"Luke.12.11\"></r>, <r v=\"Acts.9.2\"></r>, al.; of a Christian assembly, <r v=\"Jas.2.2\"></r>. By meton., of the building in which the assembly is held, <b>a synagogue</b>: <r v=\"Matt.10.17\"></r>, <r v=\"Mark.1.21\"></r>, al. (cf. Cremer, s.v. <g>ἐκκλησία</g>) </s> <sy><i>SYN.</i>: <x><g>ἐκκλησία</g></x> (q.v.) </sy>"},"G4808":{"l":"συκῆ","o":16,"ar":"<f><o>συκῆ</o> (مُدغمة من <g>συκέα</g>)، <g>-ῆς, ἡ</g> </f> <s><b>شجرة تين</b>: <r v=\"Matt.21.19-Matt.21.21\"></r>، <r v=\"Matt.24.32\"></r>، <r v=\"Mark.11.13\"></r>، <r v=\"Mark.11.20-Mark.11.21\"></r>، <r v=\"Mark.13.28\"></r>، <r v=\"Luke.13.6-Luke.13.7\"></r>، <r v=\"Luke.21.29\"></r>، <r v=\"John.1.49\"></r>، <r v=\"John.1.51\"></r>، <r v=\"Jas.3.12\"></r>، <r v=\"Rev.6.13\"></r>.†</s>","en":"<f><o>συκῆ</o> (contr. fr. <g>συκέα</g>), <g>-ῆς, ἡ</g> </f> <et> <e t=\"derivation\">(&lt; <x><g>σῦκον</g></x>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H8384\">תְּאֵנָה</h> ;] </e> </et> <s><b>a fig-tree</b>: <r v=\"Matt.21.19-Matt.21.21\"></r> <r v=\"Matt.24.32\"></r>, <r v=\"Mark.11.13\"></r>, <r v=\"Mark.11.20-Mark.11.21\"></r> <r v=\"Mark.13.28\"></r>, <r v=\"Luke.13.6-Luke.13.7\"></r> <r v=\"Luke.21.29\"></r>, <r v=\"John.1.49\"></r>, <r v=\"John.1.51\"></r>, <r v=\"Jas.3.12\"></r>, <r v=\"Rev.6.13\"></r>.†</s>"},"G4887":{"l":"συνδέω","o":1,"ar":"<f><o>συν-δέω </o></f> <s n=\"(a)\"><b>ربط معًا</b>؛ </s> <s n=\"(b)\"><b>قُيِّد مع</b>: المبني للمجهول، <r v=\"Heb.13.3\"></r>.†</s>","en":"<f><o>συν-δέω </o></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H7660\">שׁבץ</h>, etc. ;]</e> </et> <s n=\"(a)\"><b>to bind together</b>; </s> <s n=\"(b)\"><b>to bind together with</b>: pass., <r v=\"Heb.13.3\"></r>.†</s>"},"G4834":{"l":"συνπαθέω","o":2,"ar":"<f>** <o>συν-παθέω</o></f> <s><b>يشارك في الشعور، يرثي لـ</b>: مع القابل للشيء، <r v=\"Heb.4.15\"></r>؛ ومع القابل للشخص، <r v=\"Heb.10.34\"></r>.†</s>","en":"<f>** <o>συν-παθέω</o></f> <et> <e t=\"derivation\">(Rec. <g>συμπ-</g>), <g>-ῶ</g>, </e> <e t=\"septuagint\">[in LXX: <r v=\"4Macc.5.25\"></r> AR 13:23 * ;] </e> </et> <s><b>to have a fellow feeling for or with, sympathize with or in</b>: c. dat. rei, <r v=\"Heb.4.15\"></r>; dat. pers., <r v=\"Heb.10.34\"></r> (Arist., Plut., al.).†</s>"},"G4899":{"l":"συνεκλεκτός","o":1,"ar":"<f>*† <o>συν-εκ-λεκτός</o>، <g>-ή, -όν </g></f> <s><b>مختار معه، مختارة معكم</b>: <g>ἡ ἐν Βαβυλῶνι συνεκλεκτή</g>، <r v=\"1Pet.5.13\"></r>.†</s>","en":"<f>*† <o>συν-εκ-λεκτός</o>, <g>-ή, -όν </g></f> <s><b>chosen together with, co-elect</b>: <g>ἡ ἐν Βαβυλῶνι συνεκλεκτή</g> (on the meaning, v. <i>ICC</i>, in l.), <r v=\"1Pet.5.13\"></r>.†</s>"},"G4810":{"l":"σῦκον","o":4,"ar":"<f><o>σῦκον</o>، <g>-ου, τό </g></f> <s><b>تينة</b>: <r v=\"Matt.7.16\"></r>، <r v=\"Mark.11.13\"></r>، <r v=\"Luke.6.44\"></r> <r v=\"Jas.3.12\"></r>.†</s>","en":"<f><o>σῦκον</o>, <g>-ου, τό </g></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H8384\">תְּאֵנָה</h> ] </e> </et> <s><b>a fig</b>: <r v=\"Matt.7.16\"></r>, <r v=\"Mark.11.13\"></r>, <r v=\"Luke.6.44\"></r> <r v=\"Jas.3.12\"></r>.†</s>"},"G4845":{"l":"συνπληρόω","o":3,"ar":"<f><o>συν-πληρόω</o></f> <s n=\"1.\"><b>ملأ تمامًا</b>: عن سفينة تمتلئ ماءً، وكنايةً عن الذين على متنها، <r v=\"Luke.8.23\"></r>. </s> <s n=\"2.\"><b>أكمل، تمَّم</b>: عن الزمان (<r v=\"Jer.25.12\"></r>)، <r v=\"Luke.9.51\"></r>، <r v=\"Acts.2.1\"></r>.†</s>","en":"<f><o>συν-πληρόω</o></f> <et> <e t=\"derivation\">(Rec. <g>συμπ-</g>), <g>-ῶ</g>, </e> <e t=\"septuagint\">[in LXX: <r v=\"Jer.25.12\"></r> (<h n=\"H4390\">מָלֵא</h>) * ;]</e> </et> <s n=\"1.\"><b>to fill up completely</b> (Thuc., of manning ships): of a ship filling with water, and by meton., of those on board, <r v=\"Luke.8.23\"></r>. </s> <s n=\"2.\"><b>to complete, fulfil</b>: of time (<r v=\"Jer.25.12\"></r>, and v. MM, xxiv), <r v=\"Luke.9.51\"></r>, <r v=\"Acts.2.1\"></r> (on the \"durative inf.,\" v. M, <i>Pr.</i>, 233).†</s>"},"G4873":{"l":"συνανάκειμαι","o":7,"ar":"<f>**† <o>συν-ανά-κειμαι </o></f> <s><b>اتكأ مع</b> غيره أو <b>معًا</b> على المائدة: <r v=\"Matt.14.9\"></r>، <r v=\"Mark.6.22\"></r>، <r v=\"Luke.7.49\"></r>، <r v=\"Luke.14.15\"></r>؛ مع قابل الشخص، <r v=\"Matt.9.10\"></r>، <r v=\"Mark.2.15\"></r>، <r v=\"Luke.14.10\"></r>.†</s>","en":"<f>**† <o>συν-ανά-κειμαι </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"3Macc.5.39\"></r> * ;]</e> </et> <s><b>to recline with</b> or <b>together</b> at table: <r v=\"Matt.14.9\"></r>, <r v=\"Mark.6.22\"></r>, <r v=\"Luke.7.49\"></r> <r v=\"Luke.14.15\"></r>; c. dat. pers., <r v=\"Matt.9.10\"></r>, <r v=\"Mark.2.15\"></r>, <r v=\"Luke.14.10\"></r>.†</s>"},"G4818":{"l":"συνλυπέω","o":1,"ar":"<f><o>συν-λυπέω</o></f> <s>في اليونانية الكلاسيكية: <b>جعله يحزن مع غيره</b>. المبني للمجهول، <b>حزن</b> مشاركةً ووجدانًا: يليه <g>ἐπί</g> مع القابل، <r v=\"Mark.3.5\"></r>.†</s>","en":"<f><o>συν-λυπέω</o></f> <et> <e t=\"derivation\">(Rec. <g>συλλ-</g>), <g>-ῶ</g>, </e> <e t=\"septuagint\">[in LXX: <r v=\"Ps.69.20\"></r>, <r v=\"Isa.51.19\"></r> (<h n=\"H5110\">נוּד</h>) * ;] </e> </et> <s><b>to make to grieve with</b> (Arist.). Pass., <b>to be moved to grief</b> by sympathy: seq. <g>ἐπί</g>, c. dat., <r v=\"Mark.3.5\"></r>.†</s>"},"G4801":{"l":"συνζεύγνυμι","o":2,"ar":"<f><o>συν-ζεύγνυμι</o></f> <s><b>ربط معًا تحت نير واحد</b>: مجازيًا، عن الاتحاد في الزواج، <r v=\"Matt.19.6\"></r>، <r v=\"Mark.10.9\"></r>.†</s>","en":"<f><o>συν-ζεύγνυμι</o></f> <et> <e t=\"derivation\">(Rec. <g>συζ-</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Ezek.1.11\"></r>, <r v=\"Ezek.1.23\"></r> (<h n=\"H2266\">חבר</h>) * ;] </e> </et> <s><b>to yoke to­gether</b>: metaph., of union in wedlock, <r v=\"Matt.19.6\"></r>, <r v=\"Mark.10.9\"></r>.†</s>"},"G4844":{"l":"συμπόσιον","o":1,"ar":"<f><o>συμπόσιον</o>، <g>-ου, τό</g></f> <s n=\"1.\"><b>وليمة شراب</b> </s> <s n=\"2.\">كنايةً عن الجماعة نفسها، أي المدعوّين؛ وفي الجمع <g>σ. σ.</g> (أسلوب دارج)، <b>رفاقًا رفاقًا</b> أو <b>جماعاتٍ جماعات</b>: <r v=\"Mark.6.39\"></r>.†</s>","en":"<f><o>συμπόσιον</o>, <g>-ου, τό</g></f> <et> <e t=\"derivation\">(&lt; <g>συμπίνω</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Ezra.7.7\"></r> (<h n=\"H4960\">מִשְׁתֶּה</h> <h n=\"H3196\">יַיִן</h>) <r v=\"Ezra.4.17\"></r>, <r v=\"1Macc.16.16\"></r>, <r v=\"2Macc.2.27\"></r>, <r v=\"3Macc.4.16\"></r> <r v=\"3Macc.5.36\"></r> <r v=\"3Macc.6.33\"></r>; <g>σ. οἴνου</g>, <r v=\"Sir.31.31\"></r> <r v=\"Sir.32.5\"></r>, <r v=\"Sir.49.1\"></r> * ;] </e> </et> <s n=\"1.\"><b>a drinking party</b> </s> <s n=\"2.\">By meton., of the party itself, the guests (Plut); pl., <g>σ. σ.</g> (colloq.; v. M, <i>Pr.</i>, 97), <b>in parties</b> or <b>companies</b>: <r v=\"Mark.6.39\"></r>.†</s>"},"G4846":{"l":"συνπνίγω","o":5,"ar":"<f>* <o>συν-πνίγω</o>، </f> <s><b>خنق</b>: عن ازدحام الجمع، <r v=\"Luke.8.42\"></r>. مجازيًا، عن الزرع، <g>τ. λόγον</g>، <r v=\"Matt.13.22\"></r>، <r v=\"Mark.4.7\"></r>، <r v=\"Mark.4.19\"></r>، <r v=\"Luke.8.14\"></r>.†</s>","en":"<f>* <o>συν-πνίγω</o> (Rec. <g>συμπ-</g>), </f> <s><b>to choke</b>: of thronging by a crowd, <r v=\"Luke.8.42\"></r>. Fig., of seed, <g>τ. λόγον</g>, <r v=\"Matt.13.22\"></r>, <r v=\"Mark.4.7\"></r>, <r v=\"Mark.4.19\"></r>, <r v=\"Luke.8.14\"></r>.†</s>"},"G4827":{"l":"συνμαθητής","o":1,"ar":"<f>* <o>συν-μαθητής</o>، <g>-οῦ, ὁ</g> </f> <s><b>تلميذ رفيق، زميل في التلمذة</b>: <r v=\"John.11.16\"></r>.†</s>","en":"<f>* <o>συν-μαθητής</o> (Rec. <g>συμμ-</g>), <g>-οῦ, ὁ</g> </f> <s><b>a fellow-disciple</b>: <r v=\"John.11.16\"></r> (on the use of <g>συν-</g> in such compounds as this, v. Rutherford, <i>NPhr.</i>, 255 f.).†</s>"},"G4843":{"l":"συνπεριλαμβάνω","o":1,"ar":"<f><o>συν-περι-λαμβάνω</o>، </f> <s n=\"1.\"><b>أحاط، ضمّ</b> (<r v=\"Ezek.5.3\"></r> (<h n=\"H6696\">צוּר</h>) *). </s> <s n=\"2.\"><b>احتضن، اعتنق</b>: مع منصوب الشخص، <r v=\"Acts.20.10\"></r>.†</s>","en":"<f><o>συν-περι-λαμβάνω</o> (Rec. <g>συμπ-</g>), </f> <s n=\"1.\"><b>to enclose</b> (<r v=\"Ezek.5.3\"></r> (<h n=\"H6696\">צוּר</h>) *). </s> <s n=\"2.\"><b>to embrace</b>: c. acc. pers., <r v=\"Acts.20.10\"></r>.†</s>"},"G4814":{"l":"συνλαλέω","o":6,"ar":"<f><o>συν-λαλέω</o></f> <s><b>يتكلم مع، يتحادث معًا</b>: مع القابل للشخص، <r v=\"Mark.9.4\"></r>، <r v=\"Luke.9.30\"></r> <r v=\"Luke.22.4\"></r>؛ يليه <g>μετά</g> مع المضاف إليه، <r v=\"Matt.17.3\"></r>، <r v=\"Acts.25.12\"></r>؛ <g>πρός</g> مع المنصوب، <r v=\"Luke.4.36\"></r>.†</s>","en":"<f><o>συν-λαλέω</o></f> <et> <e t=\"derivation\"> (Rec. <g>συλλ-</g>), <g>-ῶ</g>, </e> <e t=\"septuagint\"> [in LXX for <h n=\"H????\">דּבר</h>pi.,<h n=\"H????\">שִׂיחַ</h>;] </e> </et> <s><b>to talk with or together</b>: (c. dat. pers., <r v=\"Mark.9.4\"></r>, <r v=\"Luke.9.30\"></r> <r v=\"Luke.22.4\"></r>; seq. <g>μετά</g>, c. gen., <r v=\"Matt.17.3\"></r>, <r v=\"Acts.25.12\"></r>; . <g>πρός</g>, c. acc., <r v=\"Luke.4.36\"></r>.†</s>"},"G4836":{"l":"συνπαραγίνομαι","o":1,"ar":"<f><o>συν-παρα-γίνομαι</o></f> <s n=\"1.\"><b>يأتي معًا أو يحضر معًا</b>: يليه <g>ἐπί</g>، <r v=\"Luke.23.48\"></r>. </s> <s n=\"2.\"><b>يأتي للنجدة</b> (<r v=\"2Tim.4.16\"></r>).†</s>","en":"<f><o>συν-παρα-γίνομαι</o></f> <et> <e t=\"derivation\">(Rec. <g>συμπ-</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Ps.83.8\"></r> (<h n=\"H3867\">לוה</h> ni.) * ;] </e> </et> <s n=\"1.\"><b>to come up or be present together</b>: seq. <g>ἐπί</g>, <r v=\"Luke.23.48\"></r>. </s> <s n=\"2.\"><b>to come up to assist</b> (Thuc., al.; <r v=\"2Tim.4.16\"></r>, Rec.).†</s>"},"G4803":{"l":"συνζήτησις","o":null,"ar":"<f>*† <o>συν-ζήτησις</o>، <g>-εως, ἡ</g> </f> <s><b>مباحثة</b>: <r v=\"Acts.28.29\"></r>.†</s>","en":"<f>*† <o>συν-ζήτησις</o> (Rec. <g>συζ-</g>), <g>-εως, ἡ</g> </f> <s><b>disputation</b>: <r v=\"Acts.28.29\"></r> (WH, R, txt., om.).†</s>"},"G4816":{"l":"συλλέγω","o":8,"ar":"<f><o>συλ-λέγω </o></f> <s><b>جمع، حصد، لمّ</b>: مع منصوب الشيء، <r v=\"Matt.13.28-Matt.13.30\"></r>؛ وفي المبني للمجهول، <r v=\"Matt.13.40\"></r>؛ مع المنصوب يليه <g>ἀπό</g>، <r v=\"Matt.7.16\"></r>؛ وكذلك يليه <g>ἐκ</g>، <r v=\"Matt.13.41\"></r>، <r v=\"Luke.6.44\"></r>؛ ويليه <g>εἰς</g>، <r v=\"Matt.13.48\"></r>.†</s>","en":"<f><o>συλ-λέγω </o></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3950\">לקט</h> ;] </e> </et> <s><b>to bring together, collect, gather up</b>: c. acc. rei, <r v=\"Matt.13.28-Matt.13.30\"></r>; pass., <r v=\"Matt.13.40\"></r>; c. acc., seq. <g>ἀπό</g>, <r v=\"Matt.7.16\"></r>; id. seq. <g>ἐκ</g>, <r v=\"Matt.13.41\"></r>, <r v=\"Luke.6.44\"></r>; seq. <g>εἰς</g>, <r v=\"Matt.13.48\"></r>.†</s>"},"G4807":{"l":"συκάμινος","o":1,"ar":"<f><o>συκάμινος</o>، <g>-ου, ἡ </g></f> <s><b>شجرة التوت</b> </s> <s><b>شجرة السيكامين</b>: <r v=\"Luke.17.6\"></r>. (في السبعينية يبدو أن <g>σ.</g> يقابل <g>συκόμορος</g> (انظر تحت مدخل <g>συκομορέα</g>)، لكن لوقا يميّز بينهما.) †</s>","en":"<f><o>συκάμινος</o>, <g>-ου, ἡ </g></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H8256\">שִׁקְמָה</h> (pl.) ;] </e> </et> <s><b>the mulberry tree</b> </s> <et> <e t=\"derivation\">(Lat. <l>morus</l>; cf. <g>μόρον</g>, <r v=\"1Macc.6.34\"></r> *), </e> </et> <s><b>the sycamine</b>: <r v=\"Luke.17.6\"></r>. (In LXX, <g>σ.</g> appears to represent the <g>συκόμορος</g> (v.s. <g>συκομορέα</g>), but St. Luke distinguishes between the two; v. <i>ICC</i>, in l.; <i>DB</i>, iv, 634.) †</s>"},"G4824":{"l":"συμβούλιον","o":8,"ar":"<f>**† <o>συμβούλιον</o>، <g>-ου, τό</g></f> <s>= <g>συμβουλία</g> في اليونانية الكلاسيكية، </s> <s n=\"1.\"><b>مشورة</b>: <g>σ. λαμβάνειν</g>، <r v=\"Matt.12.14\"></r>، <r v=\"Matt.22.15\"></r>، <r v=\"Matt.27.1\"></r>، <r v=\"Matt.27.7\"></r>، <r v=\"Matt.28.12\"></r>؛ <g>διδόναι</g>، <r v=\"Mark.3.6\"></r>؛ <g>ποιεῖν</g>، <r v=\"Mark.15.1\"></r>. </s> <s n=\"2.\">كناية، <b>مجلس</b> (قارن <r v=\"4Macc.17.17\"></r>): <r v=\"Acts.25.12\"></r>.†</s>","en":"<f>**† <o>συμβούλιον</o>, <g>-ου, τό</g></f> <et> <e t=\"derivation\">(&lt; <x><g>σύμβουλος</g></x>), </e> <e t=\"septuagint\">[in LXX: <r v=\"4Macc.17.17\"></r> <h>א</h> * ;] </e> </et> <s>a word of the Græco-Roman period (of. Lat. <l>consilium</l>, and v. Deiss., <i>BS</i>, 238) = cl. <g>συμβουλία</g> (Arist., Xen.), </s> <s n=\"1.\"><b>counsel</b>: <g>σ. λαμβάνειν</g>, <r v=\"Matt.12.14\"></r> <r v=\"Matt.22.15\"></r> <r v=\"Matt.27.1\"></r>, <r v=\"Matt.27.7\"></r> <r v=\"Matt.28.12\"></r>; <g>διδόναι</g>, <r v=\"Mark.3.6\"></r> (<g>ποιεῖν</g>, Rec.); <g>ποιεῖν</g>, <r v=\"Mark.15.1\"></r> (<g>ἑτοιμάζειν</g>, WH, mg.). </s> <s n=\"2.\">By meton., <b>a council</b> (<r v=\"4Macc.17.17\"></r><h>א</h>; <g>συνέδριον</g>, AR): <r v=\"Acts.25.12\"></r> (v. MM, xxiv).†</s>"},"G4868":{"l":"συναίρω","o":3,"ar":"<f><o>συν-αίρω </o></f> <s><b>رفع معًا</b>: <g>σ. λόγον</g>، <b>حاسب، صفّى الحساب</b>، <r v=\"Matt.18.23-Matt.18.24\"></r>؛ يليه <g>μετά</g> مع المضاف إليه للشخص، <r v=\"Matt.25.19\"></r>.†</s>","en":"<f><o>συν-αίρω </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Exod.23.5\"></r> (<h n=\"H5800\">עזב</h>) * ;] </e> </et> <s><b>to take up together</b>: <g>σ. λόγον</g> (of which there are several exx. in <g>π.</g>; v. Deiss., <i>LAE</i>, 118 f.; MM, i, xxiv; M, <i>Pr.</i>, 160), <b>to settle accounts</b>, <r v=\"Matt.18.23-Matt.18.24\"></r>; seq. <g>μετά</g>, C. gen. pers., <r v=\"Matt.25.19\"></r>.†</s>"},"G4871":{"l":"συναλίζω","o":1,"ar":"<f>** <o>συν-αλίζω </o></f> <s><b>اجتمع مع</b>: <r v=\"Acts.1.4\"></r> (وفي الهامش: <b>أكل مع</b>).†</s>","en":"<f>** <o>συν-αλίζω </o></f> <et> <e t=\"septuagint\">[in Al.: <r v=\"Ps.141.4\"></r> * ;]</e> </et> <s><b>to assemble with</b>: <r v=\"Acts.1.4\"></r> (EV, mg., <b>eating with</b>, but on this rendering and on the force of the pres. ptcp. here, v. Field, <i>Notes</i>, 110).†</s>"},"G4872":{"l":"συναναβαίνω","o":2,"ar":"<f><o>συν-ανα-βαίνω </o></f> <s><b>صعد مع</b>: مع القابل للشخص، يليه <g>εἰς</g> مع منصوب المكان، <r v=\"Mark.15.41\"></r>، <r v=\"Acts.13.31\"></r>.†</s>","en":"<f><o>συν-ανα-βαίνω </o></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H5927\">עלה</h> ;] </e> </et> <s><b>to go up with</b>: c. dat. pers., seq. <g>εἰς</g>, c. acc. loc., <r v=\"Mark.15.41\"></r>, <r v=\"Acts.13.31\"></r>.†</s>"},"G4895":{"l":"σύνειμι_2","o":3,"ar":"<f><o>σύν-ειμι</o></f> <s><b>كان مع</b>: <r v=\"Luke.9.18\"></r>، <r v=\"Acts.22.11\"></r>.†</s>","en":"<f><o>σύν-ειμι</o></f> <et> <e t=\"derivation\">(&lt; <g>εἰμί</g> <i>to be</i>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Jer.3.20\"></r> (<h n=\"H7453\">רֵעַ</h>), al. ;] </e> </et> <s><b>to be with</b>: <r v=\"Luke.9.18\"></r> (WH, mg., <g>συνήντησαν</g>), <r v=\"Acts.22.11\"></r>.†</s>"},"G4820":{"l":"συνβάλλω","o":6,"ar":"<f><o>συν-βάλλω</o></f> <s><b>ألقى معًا، جمع معًا</b>، ومن ثم، </s> <s n=\"(a)\">عن الكلام (يليه <g>λόγους</g>)، <b>تباحث، تشاور</b> (أي <g>λόγους</g>): مع القابل للشخص، <r v=\"Luke.11.53\"></r>، وقارن <r v=\"Acts.17.18\"></r>؛ يليه <g>πρὸς ἀλλήλους</g>، <r v=\"Acts.4.15\"></r>؛ </s> <s n=\"(b)\"><b>تأمّل، فكّر، تفكّر في</b>: <g>ἐν τ. καρδίᾳ</g>، <r v=\"Luke.2.19\"></r>؛ </s> <s n=\"(c)\"><b>التقى بـ، صادف</b>: <r v=\"Acts.20.14\"></r>؛ بمعنى عدائي، <g>εἰς πόλεμον</g>، مع القابل، <r v=\"Luke.14.31\"></r>؛ </s> <s n=\"(d)\">الصيغة الوسطى، <b>ساعد، أفاد (أسهم)</b>: <r v=\"Acts.18.27\"></r>.†</s>","en":"<f><o>συν-βάλλω</o></f> <et> <e t=\"derivation\">(Rec. <g>συμ-</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"2Chr.25.19\"></r> (<h n=\"H1624\">גּרה</h> hith.), <r v=\"Isa.46.6\"></r> (<h n=\"H2107\">זוּל</h>), <r v=\"Jer.43.3\"></r> (<h n=\"H5496\">סוּת</h> hi.), <r v=\"Wis.5.8\"></r>, al. ;] </e> </et> <s><b>to throw together</b>, hence, </s> <s n=\"(a)\">of speech (seq. <g>λόγους</g>, Eur., al.), <b>to discuss, confer</b> (sc. <g>λόγους</g>): c. dat. pers., <r v=\"Luke.11.53\"></r>, WH, mg., <r v=\"Acts.17.18\"></r>; seq. <g>πρὸς ἀλλήλους</g>, <r v=\"Acts.4.15\"></r>; </s> <s n=\"(b)\"><b>to reflect, consider, ponder</b>: <g>ἐν τ. καρδίᾳ</g>, <r v=\"Luke.2.19\"></r>; </s> <s n=\"(c)\"><b>to meet with, fall in with</b>: <r v=\"Acts.20.14\"></r>; in hostile sense, <g>εἰς πόλεμον</g>, c. dat. (<g>εἰς μάχην</g>, Polyb.), <r v=\"Luke.14.31\"></r>; </s> <s n=\"(d)\">mid., <b>to contribute</b> (Polyb., al.; cf. MM, xxiv): <r v=\"Acts.18.27\"></r>.†</s>"},"G4856":{"l":"συμφωνέω","o":6,"ar":"<f><o>συμ-φωνέω</o>، <g>-ῶ</g>، </f> <s>أصلاً (في اليونانية الكلاسيكية): <b>توافق في الصوت، انسجم</b>. مجازيًا، </s> <s n=\"(a)\"><b>اتفق مع، اتفقوا معًا</b>: <r v=\"Luke.5.36\"></r>؛ مع القابل للشيء، <r v=\"Acts.15.15\"></r>؛ يليه <g>περί</g>، <r v=\"Matt.18.19\"></r>؛ المبني للمجهول، مع القابل للشخص، <g>συνεφωνήθη ὑμῖν</g>، <r v=\"Acts.5.9\"></r>؛ </s> <s n=\"(b)\"><b>اتفق</b> على ثمن: مع القابل للشخص، والمضاف إليه للثمن، <r v=\"Matt.20.13\"></r>؛ يليه <g>μετά . . . ἐκ</g>، <r v=\"Matt.20.2\"></r>.†</s>","en":"<f><o>συμ-φωνέω</o>, <g>-ῶ</g>, </f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Gen.14.3\"></r> (<h n=\"H2266\">חבר</h>) <r v=\"2Sam.12.8\"></r> (9) (<h n=\"H225\">אוֺת</h> ni.), <r v=\"Isa.7.2\"></r> (<h n=\"H5117\">נוּחַ</h>), <r v=\"4Macc.14.6\"></r> * ;]</e> </et> <s>prop., <b>to agree in sound, be in harmony</b> (Plat., Arist.). Metaph., </s> <s n=\"(a)\"><b>to agree with, agree together</b>: <r v=\"Luke.5.36\"></r>; c. dat. rei, <r v=\"Acts.15.15\"></r>; seq. <g>περί</g>, <r v=\"Matt.18.19\"></r>; pass., c. dat. pers., <g>συνεφωνήθη ὑμῖν</g>, <r v=\"Acts.5.9\"></r>; </s> <s n=\"(b)\"><b>to agree</b> as to a price (Polyb., Diod.): c. dat. pers., gen. pret., <r v=\"Matt.20.13\"></r>; seq. <g>μετά . . . ἐκ</g>, <r v=\"Matt.20.2\"></r>.†</s>"},"G4848":{"l":"συνπορεύομαι","o":4,"ar":"<f><o>συν-πορεύομαι</o></f> <s n=\"1.\"><b>سافر معًا، سار مع</b>: مع القابل للشخص، <r v=\"Luke.7.11\"></r> <r v=\"Luke.14.25\"></r> <r v=\"Luke.24.15\"></r>. </s> <s n=\"2.\"><b>اجتمع (جاء معًا)</b>: <r v=\"Mark.10.1\"></r>.†</s>","en":"<f><o>συν-πορεύομαι</o></f> <et> <e t=\"derivation\">(Rec. <g>σνμπ-</g>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H1980\">הלךְ</h> ;] </e> </et> <s n=\"1.\"><b>to journey together</b> (Plat., al.): c. dat. pers., <r v=\"Luke.7.11\"></r> <r v=\"Luke.14.25\"></r> <r v=\"Luke.24.15\"></r>. </s> <s n=\"2.\"><b>to come together</b>: <r v=\"Mark.10.1\"></r> (Plut., al.).†</s>"},"G4870":{"l":"συνακολουθέω","o":3,"ar":"<f>** <o>συν-ακολουθέω</o>، <g>-ῶ </g></f> <s><b>تبع مع، رافق</b>: مع القابل للشخص، <r v=\"Mark.14.51\"></r>، <r v=\"Luke.23.49\"></r>؛ يليه <g>μετά</g>، مع المضاف إليه للشخص، <r v=\"Mark.5.37\"></r>.†</s>","en":"<f>** <o>συν-ακολουθέω</o>, <g>-ῶ </g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"2Macc.2.4\"></r>, <r v=\"2Macc.2.6\"></r> * ;] </e> </et> <s><b>to follow along with, accompany</b>: c. dat. pers., <r v=\"Mark.14.51\"></r>, <r v=\"Luke.23.49\"></r>; seq. <g>μετά</g>, c. gen. pers., <r v=\"Mark.5.37\"></r>.†</s>"},"G4802":{"l":"συνζητέω","o":10,"ar":"<f><o>συν-ζητέω</o></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>بحث أو فحص مع غيره</b>. </s> <s n=\"2.\">في العهد الجديد، <b>تباحث، تحاور، جادل</b>: <r v=\"Mark.1.27\"></r> <r v=\"Mark.12.28\"></r>، <r v=\"Luke.24.15\"></r>؛ يليه سؤال غير مباشر، <r v=\"Mark.9.10\"></r>؛ مع قابل الشخص، <r v=\"Mark.8.11\"></r> <r v=\"Acts.6.9\"></r>؛ يليه <g>πρός</g>، مع منصوب الشخص، <r v=\"Mark.9.14\"></r>، <r v=\"Mark.9.16\"></r>، <r v=\"Acts.9.29\"></r>؛ ويليه كذلك سؤال غير مباشر، <r v=\"Luke.22.23\"></r>.†</s>","en":"<f><o>συν-ζητέω</o></f> <et> <e t=\"derivation\">(Rec. <g>συζ-</g>), <g>-ῶ</g>, </e> <e t=\"septuagint\">[in LXX: <r v=\"Neh.2.4\"></r> AB<i>1</i> (<h n=\"H1245\">בּקשׁ</h> pi.) * ;] </e> </et> <s n=\"1.\"><b>to search or examine together</b> (Plat.). </s> <s n=\"2.\">In NT (and <g>π.</g>, v. MM, xxiii; also in MGr., v. Kennedy, <i>Sources</i>, 155),<b> to discuss, dispute</b>: <r v=\"Mark.1.27\"></r> <r v=\"Mark.12.28\"></r>, <r v=\"Luke.24.15\"></r>; seq. quæst. indir., <r v=\"Mark.9.10\"></r>; c. dat. pers., <r v=\"Mark.8.11\"></r> <r v=\"Acts.6.9\"></r>; seq. <g>πρός</g>, c. acc pers., <r v=\"Mark.9.14\"></r>, <r v=\"Mark.9.16\"></r>, <r v=\"Acts.9.29\"></r>; id. seq. quæst. indir., <r v=\"Luke.22.23\"></r>.†</s>"},"G4884":{"l":"συναρπάζω","o":4,"ar":"<f><o>συν-αρπάζω </o></f> <s>صيغة «تامّة المعنى» من <g>ἁοπάζω</g>، </s> <s n=\"(a)\"><b>خطف وحمل بعيدًا</b> (وهو الأكثر شيوعًا): <r v=\"Acts.27.15\"></r>؛ </s> <s n=\"(b)\"><b>قبض على وأمسك</b>: <r v=\"Luke.8.29\"></r>، <r v=\"Acts.6.12\"></r> <r v=\"Acts.19.29\"></r>.†</s>","en":"<f><o>συν-αρπάζω </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Prov.6.25\"></r> (<h n=\"H3947\">לקח</h>), <r v=\"2Macc.3.27\"></r> <r v=\"2Macc.4.41\"></r>, <r v=\"4Macc.5.4\"></r> * ;] </e> </et> <s>\"perfective \" of <g>ἁοπάζω</g> (v. M, <i>Pr.</i>, 113), </s> <s n=\"(a)\"><b>to seize and carry away</b> (so most commonly) : <r v=\"Acts.27.15\"></r>; </s> <s n=\"(b)\"><b>to seize and hold</b>: <r v=\"Luke.8.29\"></r>, <r v=\"Acts.6.12\"></r> <r v=\"Acts.19.29\"></r>.†</s>"},"G4858":{"l":"συμφωνία","o":1,"ar":"<f><o>συμφωνία</o>، <g>-ας, ἡ</g></f> <s n=\"1.\"><b>توافق الأصوات، موسيقى، أنغام</b>: <r v=\"Luke.15.25\"></r> </s> <s n=\"2.\">في السبعينية وعند الكتّاب المتأخرين: <b>آلة موسيقية</b> (دانيال، في المواضع المذكورة).†</s>","en":"<f><o>συμφωνία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>σύμφωνος</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Dan.3.5\"></r>, <r v=\"Dan.3.15\"></r>, <r v=\"Dan.3.7\"></r>, <r v=\"Dan.3.10\"></r> (<h n=\"H5481\">סוּמפֹּנְיָה</h>) <r v=\"4Macc.14.3\"></r> A * ;] </e> </et> <s n=\"1.\"><b>symphony, music</b>: <r v=\"Luke.15.25\"></r> </s> <s n=\"2.\"><b>a musical instrument</b> (Polyb., al.; Da, ll. c.; v MM, xxiv).†</s>"},"G4817":{"l":"συλλογίζομαι","o":1,"ar":"<f><o>συλ-λογίζομαι </o></f> <s n=\"1.\"><b>حسب، أحصى</b>. </s> <s n=\"2.\"><b>تفكّر، تحاور</b>: <r v=\"Luke.20.5\"></r>.†</s>","en":"<f><o>συλ-λογίζομαι </o></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2803\">חשׁב</h> pi. ;]</e> </et> <s n=\"1.\"><b>to compute</b>. </s> <s n=\"2.\"><b>to reason</b>: <r v=\"Luke.20.5\"></r>.†</s>"},"G4840":{"l":"συνπάρειμι","o":1,"ar":"<f><o>συν-πάρειμι</o></f> <s><b>حضر معًا أو مع</b>: مع قابل الشخص، <r v=\"Acts.25.24\"></r>.†</s>","en":"<f><o>συν-πάρειμι</o></f> <et> <e t=\"derivation\">(Rec. <g>σνμπ-</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Tob.12.12\"></r> ΑΒ, <r v=\"Prov.8.27\"></r> (?), <r v=\"Wis.9.10\"></r> * ;] </e> </et> <s><b>to be present together or with</b>: c. dat. pers., <r v=\"Acts.25.24\"></r>.†</s>"},"G4809":{"l":"συκομορέα","o":null,"ar":"<f>*† <o>συκο-μορέα</o> (ويرد <g>-μωραία</g>، <g>-μωρέα</g>)، <g>-ας, ἡ</g>، والأكثر شيوعًا (وهكذا عند أكيلا وسيماخوس، <r v=\"Ps.78.47\"></r>، <r v=\"Isa.9.10\"></r>) <g>συκόμορος</g> </f> <s><b>تينة توت، جمّيزة</b>: <r v=\"Luke.19.4\"></r> (قارن <g>συκάμινος</g>).†</s>","en":"<f>*† <o>συκο-μορέα</o> (Rec. <g>-μωραία</g>, L, <g>-μωρέα</g>), <g>-ας, ἡ</g>, more commonly (so Aq., Sm., <r v=\"Ps.78.47\"></r>, <r v=\"Isa.9.10\"></r>) <g>συκόμορος</g> </f> <et> <e t=\"derivation\">(&lt; <x><g>σῦκον</g></x> + <g>μόρον</g>, <b>the black mulberry</b>), </e> </et> <s><b>a fig-mulberry, a sycamore</b>: <r v=\"Luke.19.4\"></r> (cf. <g>συκάμινος</g>).†</s>"},"G4867":{"l":"συναθροίζω","o":2,"ar":"<f><o>συν-αθροίζω </o></f> <s><b>جمع، حشد</b>: مع منصوب الشخص، <r v=\"Acts.19.25\"></r>؛ المبني للمجهول، <r v=\"Acts.12.12\"></r>.†</s>","en":"<f><o>συν-αθροίζω </o></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H6908\">קבץ</h> ;] </e> </et> <s><b>to gather together, assemble</b>: c. acc. pers., <r v=\"Acts.19.25\"></r>; pass., <r v=\"Acts.12.12\"></r>.†</s>"},"G4896":{"l":"σύνειμι","o":3,"ar":"<f>* <o>σύν-ειμι</o></f> <s><b>جاء معًا، اجتمع</b>: <r v=\"Luke.8.4\"></r>.†</s>","en":"<f>* <o>σύν-ειμι</o></f> <et> <e t=\"derivation\">(&lt; <g>εἶμι</g>, <i>to go</i>), </e> </et> <s><b>to come together</b>: <r v=\"Luke.8.4\"></r>.†</s>"},"G4892":{"l":"συνέδριον","o":22,"ar":"<f><o>συνέδριον</o>، <g>-ου, τό</g></f> <s n=\"1.\"><b>مجلس</b> (وفي السبعينية): عن محكمة يهودية محلية، <r v=\"Matt.10.17\"></r>، <r v=\"Mark.13.9\"></r>. </s> <s n=\"2.\">المحكمة الدينية العليا لليهود، <b>السنهدريم</b> (أي סַנְהֵדְרִין في التلمود = <g>συνέδριον</g>): <r v=\"Matt.5.22\"></r> <r v=\"Matt.26.59\"></r>، <r v=\"Mark.14.55\"></r> <r v=\"Mark.15.1\"></r>، <r v=\"Luke.22.66\"></r>، <r v=\"Acts.5.21\"></r>، <r v=\"Acts.5.27\"></r>، <r v=\"Acts.5.34\"></r>، <r v=\"Acts.5.41\"></r> <r v=\"Acts.6.12\"></r>، <r v=\"Acts.6.15\"></r> <r v=\"Acts.22.30\"></r> <r v=\"Acts.23.1\"></r>، <r v=\"Acts.23.6\"></r>، <r v=\"Acts.23.15\"></r>، <r v=\"Acts.23.20\"></r>، <r v=\"Acts.23.28\"></r> <r v=\"Acts.24.20\"></r>؛ عن اجتماع للسنهدريم، <r v=\"John.11.47\"></r>؛ عن مكان الاجتماع، <r v=\"Acts.4.15\"></r>.†</s>","en":"<f><o>συνέδριον</o>, <g>-ου, τό</g></f> <et> <e t=\"derivation\">(&lt; <x><g>σύν</g></x> + <g>ἕδρα</g>, <i>a seat</i>) </e> <e t=\"septuagint\">[in LXX: <r v=\"Prov.11.13\"></r> <r v=\"Prov.15.22\"></r>, <r v=\"Jer.15.17\"></r> (<h n=\"H5475\">סוֹד</h>), <r v=\"Ps.26.4\"></r> (<h n=\"H4962\">מַת</h>), <r v=\"Prov.22.10\"></r> (<h n=\"H1779\">דִּין</h>) <r v=\"Prov.26.26\"></r> (<h n=\"H6951\">קָהָל</h>); <r v=\"Prov.24.7\"></r> <r v=\"Prov.27.22\"></r> <r v=\"Prov.31.23\"></r>, <r v=\"2Macc.14.5\"></r>, <r v=\"4Macc.17.17\"></r> * ;] </e> </et> <s n=\"1.\"><b>a council</b> (Plat., Xen., al.; LXX; in <g>π., σ. τ. πρεσβυτέρων</g>, Deiss., <i>BS</i>, 156): of a local Jewish tribunal, <r v=\"Matt.10.17\"></r>, <r v=\"Mark.13.9\"></r>. </s> <s n=\"2.\">The supreme ecclesiastical court of the Jews, the <b>Sanhedrin</b> (i.e. Talmudic סַנְהֵדְרִין = <g>συνέδριον</g>): <r v=\"Matt.5.22\"></r> <r v=\"Matt.26.59\"></r>, <r v=\"Mark.14.55\"></r> <r v=\"Mark.15.1\"></r>, <r v=\"Luke.22.66\"></r>, <r v=\"Acts.5.21\"></r>, <r v=\"Acts.5.27\"></r>, <r v=\"Acts.5.34\"></r>, <r v=\"Acts.5.41\"></r> <r v=\"Acts.6.12\"></r>, <r v=\"Acts.6.15\"></r> <r v=\"Acts.22.30\"></r> <r v=\"Acts.23.1\"></r>, <r v=\"Acts.23.6\"></r>, <r v=\"Acts.23.15\"></r>, <r v=\"Acts.23.20\"></r>, <r v=\"Acts.23.28\"></r> <i>(WH, R, mg., om.)</i> <r v=\"Acts.24.20\"></r> of a meeting of the Sanhedrin, <r v=\"John.11.47\"></r>; of the place of meeting, <r v=\"Acts.4.15\"></r>.†</s>"},"G4811":{"l":"συκοφαντέω","o":2,"ar":"<f><o>συκοφαντέω</o>، <g>-ῶ</g></f> <s><b>قام بدور</b> <g>συκοφάντης</g>، <b>وشى، اتّهم زورًا</b>: <r v=\"Luke.3.14\"></r>، <r v=\"Luke.19.8\"></r> (الترجمة المنقحة: <b>ابتزّ ظلمًا</b>).†</s>","en":"<f><o>συκοφαντέω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>σῦκον</g></x>, <x><g>φαίνω</g></x>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Gen.43.18\"></r> (<h n=\"H1556\">גּלל</h> hithpo.), <r v=\"Lev.19.11\"></r> (<h n=\"H8266\">שׁקר</h> pi.), <r v=\"Job.35.9\"></r>, <r v=\"Ps.119.122\"></r>, <r v=\"Prov.14.31\"></r> <r v=\"Prov.22.16\"></r> <r v=\"Prov.28.3\"></r>, <r v=\"Eccl.4.1\"></r> (<h n=\"H6231\">עשׁק</h>) *;] </e> </et> <s><b>to act the</b> <g>συκοφάντης</g> (on conjectures as to the origin of the term, v. LS, s.v.), <b>to accuse falsely</b> (Aristoph., Xen., al.): <r v=\"Luke.3.14\"></r> (R, mg.) <r v=\"Luke.19.8\"></r> (RV,<b> exact wrongfully</b>; but cf. Hatch, <i>Essays</i>, 89 ff., v. also Field, <i>Notes</i>, 56 f.; MM, xxiv).†</s>"},"G4885":{"l":"συναυξάνω","o":1,"ar":"<f>** <o>συν-αυξάνω </o></f> <s><b>جعله ينمو</b> أو <b>ينمو معًا</b>. المبني للمجهول، <b>نما معًا</b>: <r v=\"Matt.13.30\"></r>.†</s>","en":"<f>** <o>συν-αυξάνω </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"2Macc.4.4\"></r>, <r v=\"4Macc.13.27\"></r> * ;] </e> </et> <s><b>to cause to increase</b> or <b>grow together</b>. Pass., <b>to grow together</b>: <r v=\"Matt.13.30\"></r> (Xen., al.).†</s>"},"G4855":{"l":"συνφύω","o":1,"ar":"<f>** <o>συν-φύω</o></f> <s><b>جعله ينمو معًا</b>. المبني للمجهول، <b>نما معًا أو مع</b>: <r v=\"Luke.8.7\"></r>.†</s>","en":"<f>** <o>συν-φύω</o></f> <et> <e t=\"derivation\">(Rec. <g>συμ-</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Wis.13.13\"></r> * ;] </e> </et> <s><b>to cause to grow together</b>. Pass., <b>to grow together or with</b> (Plat. al.): <r v=\"Luke.8.7\"></r>.†</s>"},"G4860":{"l":"συμψηφίζω","o":1,"ar":"<f><o>συμ-ψηφίζω </o></f> <s><b>حسب معًا، أحصى</b>: <r v=\"Acts.19.19\"></r>.†</s>","en":"<f><o>συμ-ψηφίζω </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Jer.49.20\"></r> A * ;] </e> </et> <s><b>to reckon together, count up</b>: <r v=\"Acts.19.19\"></r>.†</s>"}});A.got[48]=1})(window.ABBOTT=window.ABBOTT||{D:{},got:{}});